//: bowling scorer for a standard ten frame game

const FRAMES = 10;
const ALL_PINS = 10;

//: reject input that is not a usable list of roll numbers before scoring it
function validateRolls(rolls) {
  if (!Array.isArray(rolls)) {
    throw new TypeError('rolls must be an array of numbers');
  }
  for (const roll of rolls) {
    //: a roll is an integer count of knocked down pins, so 0..10 is the only valid range
    if (!Number.isInteger(roll) || roll < 0 || roll > ALL_PINS) {
      throw new RangeError(`invalid roll: ${roll}`);
    }
  }
}

//: the bonus rolls that follow a strike or a spare may legitimately be missing
//: from an unfinished game, so treat absent entries as zero
function rollAt(rolls, index) {
  return rolls[index] === undefined ? 0 : rolls[index];
}

function score(rolls) {
  validateRolls(rolls);

  let total = 0;
  let i = 0;

  //: frames one through nine consume one roll on a strike and two otherwise
  for (let frame = 1; frame < FRAMES; frame += 1) {
    const first = rollAt(rolls, i);

    if (first === ALL_PINS) {
      //: strike scores ten plus the next two rolls, whatever they turn out to be
      total += ALL_PINS + rollAt(rolls, i + 1) + rollAt(rolls, i + 2);
      i += 1;
      continue;
    }

    const second = rollAt(rolls, i + 1);
    total += first + second;

    if (first + second === ALL_PINS) {
      //: spare earns the single roll that follows the frame
      total += rollAt(rolls, i + 2);
    }
    i += 2;
  }

  //: the tenth frame may hold three rolls, all counted plainly with no further bonus
  const tenth = rolls.slice(i, i + 3);
  const tenthTotal = tenth.reduce((sum, roll) => sum + roll, 0);

  return total + tenthTotal;
}

//: turn a game into one readable report line for the driver output
function describeGame(name, rolls) {
  return `${name}: [${rolls.join(', ')}] => ${score(rolls)}`;
}

function main() {
  const games = {
    'perfect game': new Array(12).fill(10),
    'all spares': new Array(21).fill(5),
    'open frames': new Array(20).fill(4),
    'gutter game': new Array(20).fill(0),
    'spare finish': [10, 10, 10, 10, 10, 10, 10, 10, 10, 9, 1, 8],
  };

  for (const [name, rolls] of Object.entries(games)) {
    console.log(describeGame(name, rolls));
  }
}

main();

module.exports = { score, validateRolls, describeGame };

