// Password policy checker: a string must satisfy every rule below to be accepted.
const MIN_LENGTH = 12;
const MIN_DIGITS = 2;

// Anything that is not a letter or a digit counts as a special character.
const SPECIAL_PATTERN = /[^A-Za-z0-9]/;

function countDigits(password) {
  let digits = 0;
  for (const ch of password) {
    // String comparison works here because digits are contiguous in ASCII.
    if (ch >= '0' && ch <= '9') digits += 1;
  }
  return digits;
}

function hasTripleRepeat(password) {
  for (let i = 2; i < password.length; i += 1) {
    // Three identical characters in a row means "more than two consecutive".
    if (password[i] === password[i - 1] && password[i] === password[i - 2]) return true;
  }
  return false;
}

function startsWithDigit(password) {
  const first = password.charAt(0);
  return first >= '0' && first <= '9';
}

// Collect every broken rule so the report can explain a rejection.
function describeViolations(password) {
  const problems = [];
  if (typeof password !== 'string') {
    // A non-string input cannot be inspected further, so stop immediately.
    return ['input is not a string'];
  }
  if (password.length < MIN_LENGTH) problems.push(`shorter than ${MIN_LENGTH} characters`);
  if (!/[A-Z]/.test(password)) problems.push('no uppercase letter');
  if (!/[a-z]/.test(password)) problems.push('no lowercase letter');
  if (countDigits(password) < MIN_DIGITS) problems.push(`fewer than ${MIN_DIGITS} digits`);
  if (!SPECIAL_PATTERN.test(password)) problems.push('no special character');
  // The forbidden word is matched case-insensitively, e.g. "PassWord".
  if (password.toLowerCase().includes('password')) problems.push('contains "password"');
  if (hasTripleRepeat(password)) problems.push('more than two identical characters in a row');
  if (startsWithDigit(password)) problems.push('begins with a number');
  return problems;
}

function validate(password) {
  return describeViolations(password).length === 0;
}

function report(password) {
  if (validate(password)) return `${JSON.stringify(password)}: accepted`;
  const reasons = describeViolations(password).join('; ');
  return `${JSON.stringify(password)}: rejected (${reasons})`;
}

function main(argv) {
  // Passwords may be supplied on the command line; otherwise use a weak/strong pair.
  const candidates = argv.length > 0 ? argv : ['password123', 'Tr0ub4dor&3xyz'];
  for (const candidate of candidates) {
    console.log(report(candidate));
  }
}

main(process.argv.slice(2));

module.exports = { validate, describeViolations, report };

