const RANK_NAMES = {
  11: 'Jack',
  12: 'Queen',
  13: 'King',
  14: 'Ace',
};

// Cards are accepted as plain objects, so reject anything that cannot be scored
function validateHand(hand) {
  if (!Array.isArray(hand) || hand.length !== 5) {
    throw new TypeError('a poker hand must be an array of exactly five cards');
  }
  for (const card of hand) {
    const badSuit = !card || typeof card.suit !== 'string' || card.suit.length === 0;
    // A missing suit makes the flush test meaningless, a non-numeric value breaks sorting
    if (badSuit || typeof card.value !== 'number' || !Number.isInteger(card.value)) {
      throw new TypeError('each card needs a suit string and an integer value');
    }
  }
}

function isFlush(hand) {
  const suit = hand[0].suit;
  // Every card must repeat the suit of the first one
  return hand.every((card) => card.suit === suit);
}

function sortedValues(hand) {
  return hand.map((card) => card.value).sort((a, b) => a - b);
}

function isStraight(values) {
  for (let i = 1; i < values.length; i += 1) {
    // Consecutive values differ by exactly one; duplicates or gaps disqualify the run
    if (values[i] - values[i - 1] !== 1) return false;
  }
  return true;
}

function countValues(values) {
  const counts = new Map();
  for (const value of values) {
    counts.set(value, (counts.get(value) || 0) + 1);
  }
  return counts;
}

function nameOf(value) {
  // Face cards and the ace read better by name than by number
  return RANK_NAMES[value] || String(value);
}

function poker(hand) {
  validateHand(hand);
  const values = sortedValues(hand);
  const flush = isFlush(hand);
  const straight = isStraight(values);
  if (flush && straight) return 'straight flush';
  if (flush) return 'flush';
  if (straight) return 'straight';
  const counts = [...countValues(values).values()];
  // Four identical values leave a single odd card behind
  if (counts.includes(4)) return 'four of a kind';
  if (counts.includes(3) && counts.includes(2)) return 'full house';
  // Nothing combined, so the hand is only worth its top card
  return `high card ${nameOf(values[values.length - 1])}`;
}

function describe(hand) {
  const cards = hand.map((card) => `${nameOf(card.value)} of ${card.suit}`).join(', ');
  return `${cards} -> ${poker(hand)}`;
}

const hands = [
  [{ suit: 'hearts', value: 9 }, { suit: 'hearts', value: 10 }, { suit: 'hearts', value: 11 },
    { suit: 'hearts', value: 12 }, { suit: 'hearts', value: 13 }],
  [{ suit: 'clubs', value: 7 }, { suit: 'spades', value: 7 }, { suit: 'hearts', value: 7 },
    { suit: 'diamonds', value: 7 }, { suit: 'clubs', value: 2 }],
  [{ suit: 'clubs', value: 4 }, { suit: 'spades', value: 4 }, { suit: 'hearts', value: 4 },
    { suit: 'diamonds', value: 9 }, { suit: 'clubs', value: 9 }],
  [{ suit: 'clubs', value: 3 }, { suit: 'spades', value: 6 }, { suit: 'hearts', value: 8 },
    { suit: 'diamonds', value: 12 }, { suit: 'clubs', value: 14 }],
];

for (const hand of hands) {
  console.log(describe(hand));
}

module.exports = { poker, describe };

