// Date parsing utilities: dates are given as "YYYY-MM-DD" strings.

// A year is a leap year when divisible by 4, except centuries that are not divisible by 400.
function isLeapYear(year) {
  if (year % 400 === 0) return true;
  if (year % 100 === 0) return false;
  return year % 4 === 0;
}

// September, April, June and November are the short months.
const THIRTY_DAY_MONTHS = [4, 6, 9, 11];

function daysInMonth(year, month) {
  if (month === 2) {
    // February is the only month whose length depends on the year.
    return isLeapYear(year) ? 29 : 28;
  }
  return THIRTY_DAY_MONTHS.includes(month) ? 30 : 31;
}

// Accept only runs of ASCII digits, so "+7", " 7" and "7.0" are all rejected.
function toNumber(part) {
  if (!/^\d+$/.test(part)) return null;
  return Number(part);
}

function parse(datestring) {
  if (typeof datestring !== 'string') return [];
  const parts = datestring.split('-');
  // Exactly three fields are required: year, month and day.
  if (parts.length !== 3) return [];

  const numbers = parts.map(toNumber);
  if (numbers.some((n) => n === null)) return [];

  const [year, month, day] = numbers;
  // Year zero does not exist in this calendar, and negatives cannot be written with digits anyway.
  if (year < 1) return [];
  if (month < 1 || month > 12) return [];
  // The day must fit inside the month that was given.
  if (day < 1 || day > daysInMonth(year, month)) return [];

  return [year, month, day];
}

// Turn a parse result into a line of report output.
function describe(datestring) {
  const parsed = parse(datestring);
  if (parsed.length === 0) {
    return `${datestring} -> invalid`;
  }
  const [year, month, day] = parsed;
  // Pad month and day back to two digits so the normalised form lines up.
  const pad = (n) => String(n).padStart(2, '0');
  const kind = isLeapYear(year) ? 'leap year' : 'common year';
  return `${datestring} -> [${year}, ${month}, ${day}] (${year}-${pad(month)}-${pad(day)}, ${kind})`;
}

function main() {
  const samples = [
    '2024-02-29',
    '1900-02-29',
    '2000-02-29',
    '2023-11-30',
    '2023-11-31',
    '2023-13-01',
    '0000-01-01',
    '2023-4-5',
    '2023-04',
    '2023-04-05-06',
    'two-04-05'
  ];
  // The driver prints one report line per sample date.
  for (const sample of samples) {
    console.log(describe(sample));
  }
}

main();

module.exports = { parse, isLeapYear, daysInMonth, describe };

