const COIN_VALUES = {
  nickel: 5,
  dime: 10,
  quarter: 25,
  dollar: 100
};

const PRICES = {
  cola: 125,
  chips: 75,
  candy: 65,
  water: 100
};

// money is tracked in cents so repeated coin inserts never drift
function formatMoney(cents) {
  return '$' + (cents / 100).toFixed(2);
}

function vend(actions) {
  let balance = 0;
  const dispensed = [];

  for (const action of actions) {
    if (action.type === 'insert') {
      const value = COIN_VALUES[action.coin];
      // an unrecognised coin falls straight through to the coin return
      if (value === undefined) {
        continue;
      }
      balance += value;
    } else if (action.type === 'select') {
      const price = PRICES[action.product];
      // unknown buttons and under-funded selections are both ignored
      if (price === undefined || balance < price) {
        continue;
      }
      dispensed.push(action.product);
      const change = balance - price;
      // exact payment produces no change entry at all
      if (change > 0) {
        dispensed.push(change);
      }
      balance = 0;
    } else if (action.type === 'refund') {
      if (balance > 0) {
        dispensed.push(balance);
      }
      balance = 0;
    }
  }

  return dispensed;
}

// turn the mixed list of names and cent amounts into readable receipt lines
function describe(results) {
  return results.map(entry =>
    typeof entry === 'number' ? 'change ' + formatMoney(entry) : 'dispensed ' + entry
  );
}

function main() {
  const actions = [
    { type: 'insert', coin: 'dollar' },
    { type: 'select', product: 'cola' },      // only $1.00 in, cola costs $1.25
    { type: 'insert', coin: 'quarter' },
    { type: 'select', product: 'cola' },      // now funded, exact change
    { type: 'insert', coin: 'dollar' },
    { type: 'insert', coin: 'quarter' },
    { type: 'select', product: 'candy' },     // $1.25 in, $0.60 back
    { type: 'insert', coin: 'dime' },
    { type: 'insert', coin: 'nickel' },
    { type: 'refund' }
  ];

  const results = vend(actions);
  // raw list first, then the human-facing summary
  console.log(results);
  describe(results).forEach(line => console.log(line));
}

main();

