const STANDARD_DEDUCTION = 12000;
const SURCHARGE_THRESHOLD = 1000000;
const SURCHARGE_RATE = 0.05;

// Each bracket is [upper bound of taxable income, marginal rate applied inside it]
const BRACKETS = [
  [10000, 0.00],
  [40000, 0.12],
  [80000, 0.22],
  [Infinity, 0.24],
];

// Gross income minus the standard deduction, floored at zero so a small
// income never produces a negative taxable base
function taxableIncome(gross) {
  return Math.max(0, gross - STANDARD_DEDUCTION);
}

function bracketTax(taxable) {
  let tax = 0;
  let lower = 0;
  for (const [upper, rate] of BRACKETS) {
    // Nothing of the income reaches this bracket, so the remaining ones are empty too
    if (taxable <= lower) break;
    const amountInBracket = Math.min(taxable, upper) - lower;
    tax += amountInBracket * rate;
    lower = upper;
  }
  return tax;
}

// The surcharge is based on the *gross* income, not the deducted amount
function surcharge(gross) {
  const excess = gross - SURCHARGE_THRESHOLD;
  return excess > 0 ? excess * SURCHARGE_RATE : 0;
}

function taxFor(gross) {
  if (typeof gross !== 'number' || !Number.isFinite(gross)) {
    throw new TypeError(`income must be a finite number, got: ${gross}`);
  }
  return bracketTax(taxableIncome(gross)) + surcharge(gross);
}

function taxes(incomes) {
  // Round each liability to the nearest whole currency unit for reporting
  return incomes.map((gross) => Math.round(taxFor(gross)));
}

function formatReport(incomes) {
  const owed = taxes(incomes);
  const currency = (n) => n.toLocaleString('en-US', { maximumFractionDigits: 0 });
  return incomes.map((gross, i) => {
    // Effective rate is undefined for a zero income, so report a dash instead
    const effective = gross > 0 ? `${((owed[i] / gross) * 100).toFixed(1)}%` : '—';
    return `${currency(gross).padStart(11)} ${currency(owed[i]).padStart(11)} ${effective.padStart(7)}`;
  }).join('\n');
}

function main() {
  const sample = [0, 10000, 15000, 50000, 90000, 250000, 1500000];
  // Header widths match the column padding used in formatReport
  console.log(`${'gross'.padStart(11)} ${'tax'.padStart(11)} ${'rate'.padStart(7)}`);
  console.log(formatReport(sample));
  console.log('raw:', taxes(sample).join(', '));
}

main();

module.exports = { taxes, taxFor, taxableIncome, bracketTax, surcharge, formatReport };

