// Apparent temperature calculator: wind chill, plain temperature, or heat index.

const SEVERE_WARNING = " - SEVERE DANGER: heat stroke highly likely";

// The rothfusz regression works on Fahrenheit degrees and relative humidity in percent.
function rothfusz(t, rh) {
  return (
    -42.379 +
    2.04901523 * t +
    10.14333127 * rh -
    0.22475541 * t * rh -
    0.00683783 * t * t -
    0.05481717 * rh * rh +
    0.00122874 * t * t * rh +
    0.00085282 * t * rh * rh -
    0.00000199 * t * t * rh * rh
  );
}

// Very dry air feels cooler than the regression predicts, so a correction is removed.
function dryAdjustment(t, rh) {
  return ((13 - rh) / 4) * Math.sqrt((17 - Math.abs(t - 95)) / 17);
}

// Saturated air in the low eighties feels hotter than the regression predicts.
function humidAdjustment(t, rh) {
  return ((rh - 85) / 10) * ((87 - t) / 5);
}

// Standard NWS wind chill; the wind term is raised to the 0.16 power.
function windChill(t, windSpeed) {
  const windFactor = Math.pow(windSpeed, 0.16);
  return 35.74 + 0.6215 * t - 35.75 * windFactor + 0.4275 * t * windFactor;
}

function apparent(condition) {
  const t = condition.temperature;
  const rh = condition.humidity;

  // Below fifty degrees the wind dominates the perceived temperature.
  if (t < 50) return windChill(t, condition.windSpeed);

  // Between fifty and eighty neither wind nor humidity is significant.
  if (t <= 80) return t;

  let index = rothfusz(t, rh);

  if (rh < 13 && t >= 80 && t <= 112) {
    index -= dryAdjustment(t, rh);
  } else if (rh > 85 && t >= 80 && t <= 87) {
    index += humidAdjustment(t, rh);
  }

  return index;
}

function heat(weather) {
  return weather.map((condition) => {
    const result = apparent(condition);

    // Anything over one hundred gets reported as text carrying the warning.
    if (result > 100) return `${result}${SEVERE_WARNING}`;

    return result;
  });
}

const readings = [
  { temperature: 25, humidity: 60, windSpeed: 15 },
  { temperature: 68, humidity: 45, windSpeed: 5 },
  { temperature: 85, humidity: 10, windSpeed: 3 },
  { temperature: 84, humidity: 90, windSpeed: 2 },
  { temperature: 96, humidity: 65, windSpeed: 8 },
];

// Trim the long decimal tails only for display; the returned values stay exact.
function describe(value) {
  if (typeof value === "number") return value.toFixed(1);
  return value.replace(/^[-\d.]+/, (n) => Number(n).toFixed(1));
}

heat(readings).forEach((value, i) => {
  const { temperature, humidity } = readings[i];
  console.log(`${temperature}F at ${humidity}% RH feels like ${describe(value)}`);
});

