// Values of the seven ancient numeral symbols.
const VALUES = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 };

// V, L and D are the "half decade" symbols and may never be repeated at all.
const NEVER_REPEATED = new Set(['V', 'L', 'D']);

// Accept sloppy input (lower case, surrounding blanks) before validating symbols.
function normalize(text) {
  return String(text).trim().toUpperCase();
}

function decodeOne(text) {
  const symbols = normalize(text);

  // An empty string carries no value, so it counts as invalid.
  if (symbols.length === 0) {
    return -1;
  }

  let total = 0;
  let runLength = 0;

  for (let i = 0; i < symbols.length; i += 1) {
    const value = VALUES[symbols[i]];

    // Anything outside the seven legal symbols invalidates the whole string.
    if (value === undefined) {
      return -1;
    }

    runLength = symbols[i] === symbols[i - 1] ? runLength + 1 : 1;

    if (runLength > 1 && NEVER_REPEATED.has(symbols[i])) {
      return -1;
    }

    // I, X, C and M may appear at most three times in a row.
    if (runLength > 3) {
      return -1;
    }

    const nextValue = VALUES[symbols[i + 1]];

    // A smaller symbol standing in front of a larger one is subtracted instead.
    if (nextValue !== undefined && nextValue > value) {
      total -= value;
    } else {
      total += value;
    }
  }

  return total;
}

// Public entry point: decode every string and collect the running totals.
function roman(strings) {
  if (!Array.isArray(strings)) {
    throw new TypeError('roman() expects an array of numeral strings');
  }
  return strings.map(decodeOne);
}

function report(strings) {
  const totals = roman(strings);

  // Pair each original string with its total, flagging the rejected ones.
  return strings
    .map((text, i) => `${text} -> ${totals[i] === -1 ? 'invalid' : totals[i]}`)
    .join('\n');
}

const samples = ['MCMXC', 'MMVIII', 'MDCLXVI', 'xiv', 'IIII', 'VV', 'MCMXCIX', 'ABC', ''];
console.log(report(samples));
console.log(roman(samples).join(', '));

module.exports = { roman, decodeOne, report };

