// Minimal Markdown-to-HTML line converter.
// Only the block constructs named in the task are recognised; everything
// else falls through to a paragraph.

// Inline emphasis is applied to every line, including headers and quotes,
// so it is factored out into its own pass.
function inlineFormat(text) {
  return text
    // Double asterisks bind tighter than single ones, so strong runs first.
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/\*(.+?)\*/g, '<em>$1</em>');
}

// A header is a single '#' followed by a space; the task only asks for level one.
function isHeader(line) {
  return line.startsWith('# ');
}

function isQuote(line) {
  // Blockquotes need no space after '>', per the task description.
  return line.startsWith('>');
}

function isListItem(line) {
  return line.startsWith('- ');
}

// Strips the block marker and trims the remaining text so that
// '#   Title' and '>  quoted' do not keep their padding inside the tag.
function stripMarker(line) {
  if (isHeader(line)) return line.slice(2).trim();
  if (isQuote(line)) return line.slice(1).trim();
  if (isListItem(line)) return line.slice(2).trim();
  return line;
}

function formatLine(line) {
  // Blank (or whitespace-only) lines produce no output at all.
  if (line.trim() === '') return '';
  const body = inlineFormat(stripMarker(line));
  if (isHeader(line)) return `<h1>${body}</h1>`;
  if (isQuote(line)) return `<blockquote>${body}</blockquote>`;
  if (isListItem(line)) return `<li>${body}</li>`;
  // Anything unmarked is ordinary prose.
  return `<p>${body}</p>`;
}

function markdown(lines) {
  // Accept a single string as a convenience and split it on newlines.
  const source = typeof lines === 'string' ? lines.split('\n') : lines;
  if (!Array.isArray(source)) {
    throw new TypeError('markdown expects an array of lines or a string');
  }
  return source.map(formatLine);
}

// Driver: render a small document and report which blocks were produced.
const document = [
  '# Shopping **list**',
  '',
  '> Remember to bring *cash*.',
  '- two litres of milk',
  '- a loaf of **rye** bread',
  'That is all for *today*.'
];

const html = markdown(document);
// Empty results are dropped from the printed document but kept in the return value.
html.filter(Boolean).forEach((tag) => console.log(tag));

const headerCount = html.filter((tag) => tag.startsWith('<h1>')).length;
const itemCount = html.filter((tag) => tag.startsWith('<li>')).length;
// A short summary makes the block classification visible at a glance.
console.log(`-- ${headerCount} header(s), ${itemCount} list item(s), ${html.length} line(s) in --`);

module.exports = { markdown, formatLine, inlineFormat };

