// Restock planning for warehouse items.

const REQUIRED_FIELDS = ['dailySales', 'leadTime', 'safetyStock', 'stock', 'maxCapacity', 'minBatch'];

// Every numeric field must actually be a finite number, otherwise the arithmetic below
// would silently produce NaN order quantities.
function validate(product, index) {
  for (const field of REQUIRED_FIELDS) {
    const value = product[field];
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      throw new TypeError(`item ${index} ("${product.name}"): ${field} must be a finite number`);
    }
  }
}

// The reorder point is the stock consumed during the supplier lead time plus a buffer.
function reorderPoint(product) {
  return product.dailySales * product.leadTime + product.safetyStock;
}

function orderQuantity(product) {
  // Discontinued goods are never replenished, whatever their stock level says.
  if (product.discontinued) {
    return 0;
  }
  const point = reorderPoint(product);
  if (product.stock >= point) {
    return 0;
  }
  // Target level is twice the reorder point, so the order covers the next cycle too.
  let order = 2 * point - product.stock;
  const room = product.maxCapacity - product.stock;
  if (order > room) {
    // Never order more than the shelf space left in the warehouse.
    order = room;
  }
  if (order < product.minBatch) {
    // Suppliers refuse to ship below their minimum batch size.
    order = product.minBatch;
  }
  return Math.ceil(order);
}

function inventory(products) {
  return products.map((product, index) => {
    validate(product, index);
    return orderQuantity(product);
  });
}

// Human readable purchasing report, one line per item that needs attention.
function report(products, orders) {
  const lines = [];
  orders.forEach((order, i) => {
    const product = products[i];
    // Zero-quantity rows would only add noise to the purchase order.
    if (order > 0) {
      lines.push(`${product.name.padEnd(12)} order ${String(order).padStart(4)} (stock ${product.stock})`);
    }
  });
  return lines.join('\n');
}

const catalogue = [
  { name: 'bolts', dailySales: 40, leadTime: 5, safetyStock: 100, stock: 120, maxCapacity: 900, minBatch: 50 },
  { name: 'washers', dailySales: 10, leadTime: 3, safetyStock: 20, stock: 300, maxCapacity: 500, minBatch: 25 },
  { name: 'gaskets', dailySales: 6, leadTime: 10, safetyStock: 15, stock: 5, maxCapacity: 80, minBatch: 20 },
  { name: 'flanges', dailySales: 2, leadTime: 4, safetyStock: 1, stock: 0, maxCapacity: 400, minBatch: 60 },
  { name: 'old pumps', dailySales: 3, leadTime: 7, safetyStock: 10, stock: 0, maxCapacity: 50, minBatch: 5, discontinued: true }
];

const orders = inventory(catalogue);
console.log(orders.join(', '));
console.log(report(catalogue, orders));

module.exports = { inventory, orderQuantity, reorderPoint, report };

