const LOST_ITEM_FEE = 50.00;
const TEACHER_WAIVER_THRESHOLD = 5.00;

// Daily rate and cap per item category; dvds are deliberately uncapped
const RATE_TABLE = {
  book: { perDay: 0.20, cap: 10.00 },
  newRelease: { perDay: 0.50, cap: 10.00 },
  dvd: { perDay: 1.00, cap: Infinity }
};

function normalizeKind(kind) {
  // Accept a few spellings coming from the circulation desk export
  const cleaned = String(kind || '').trim().toLowerCase().replace(/[\s_-]+/g, '');
  if (cleaned === 'newrelease') return 'newRelease';
  if (cleaned === 'dvd') return 'dvd';
  return 'book';
}

function dailyCharge(kind, daysOverdue) {
  const { perDay, cap } = RATE_TABLE[normalizeKind(kind)];
  // The cap applies to the accumulated charge, not to the number of days
  return Math.min(daysOverdue * perDay, cap);
}

function round2(amount) {
  // Money is kept to cents to avoid floating point dust in the totals
  return Math.round(amount * 100) / 100;
}

function fineFor(item) {
  // A lost item is billed as a replacement, and no daily maths happens at all
  if (item.lost) return LOST_ITEM_FEE;

  const days = Number(item.daysOverdue) || 0;
  // Items returned on time (or early) never incur a charge
  if (days <= 0) return 0;

  const charge = dailyCharge(item.kind, days);

  // Teachers are forgiven small charges entirely, but pay larger ones in full
  if (item.teacher && charge < TEACHER_WAIVER_THRESHOLD) return 0;

  return round2(charge);
}

function fines(returns) {
  // One charge per returned item, in the same order as the input list
  return returns.map(fineFor);
}

function report(returns) {
  const charges = fines(returns);
  const lines = charges.map((charge, i) => {
    const item = returns[i];
    const title = item.title || normalizeKind(item.kind);
    return `${title.padEnd(24)} $${charge.toFixed(2)}`;
  });
  const total = charges.reduce((sum, charge) => sum + charge, 0);
  lines.push(`${'TOTAL'.padEnd(24)} $${round2(total).toFixed(2)}`);
  return lines.join('\n');
}

const todaysReturns = [
  { title: 'Dune', kind: 'book', daysOverdue: 12 },
  { title: 'Dune Messiah', kind: 'book', daysOverdue: 900 },
  { title: 'Latest Thriller', kind: 'new release', daysOverdue: 3, teacher: true },
  { title: 'Documentary Boxset', kind: 'dvd', daysOverdue: 30 },
  { title: 'Atlas of Maps', kind: 'book', daysOverdue: 40, lost: true },
  { title: 'Poems', kind: 'book', daysOverdue: -2 }
];

// Driver: print the desk's end-of-day penalty sheet
console.log(report(todaysReturns));

module.exports = { fines, fineFor, report };

