const DRYING_CEILING = 150;
const MAILLARD_CEILING = 200;
const MAX_ALLOWED_DROP = 5;

// The three phase names, in the same order as the counts returned by profile().
const PHASE_NAMES = ['drying', 'maillard', 'development'];

// A reading belongs to exactly one phase, decided purely by its own value.
function phaseIndex(temperature) {
  if (temperature < DRYING_CEILING) {
    return 0;
  }
  // The maillard reaction runs from 150 up to (but not including) 200 degrees.
  if (temperature < MAILLARD_CEILING) {
    return 1;
  }
  return 2;
}

// A stall is a fall of strictly more than five degrees between consecutive minutes.
function isStall(previous, current) {
  return previous - current > MAX_ALLOWED_DROP;
}

function profile(temperatures) {
  const counts = [0, 0, 0];
  for (let minute = 0; minute < temperatures.length; minute += 1) {
    const temperature = temperatures[minute];
    // Compare against the preceding minute before crediting the current one.
    if (minute > 0 && isStall(temperatures[minute - 1], temperature)) {
      return [-1, -1, -1];
    }
    counts[phaseIndex(temperature)] += 1;
  }
  return counts;
}

// Turn the raw counts into a human readable roast summary line.
function formatReport(counts) {
  if (counts[0] === -1) {
    return 'roast stalled';
  }
  const parts = counts.map((minutes, index) => {
    // English needs the singular form for exactly one minute.
    const unit = minutes === 1 ? 'minute' : 'minutes';
    return `${PHASE_NAMES[index]}: ${minutes} ${unit}`;
  });
  const total = counts.reduce((sum, minutes) => sum + minutes, 0);
  return `${parts.join(', ')} (total ${total})`;
}

function main() {
  const roasts = [
    [100, 140, 160, 210],
    [90, 120, 149, 151, 180, 199, 200, 205, 220],
    [120, 160, 150, 140, 200],
    [],
  ];
  for (const readings of roasts) {
    const counts = profile(readings);
    // Show the input alongside the verdict so the phases can be checked by hand.
    console.log(`[${readings.join(', ')}] -> ${formatReport(counts)}`);
  }
}

main();

module.exports = { profile, phaseIndex, isStall, formatReport };

