//
// UPC-A barcode scanner: recompute the check digit and compare it with the
// digit printed at the end of the code.
//

// Strips surrounding whitespace and common separators so codes copied from a
// label ("0 36000 29145 2") are accepted as well.
function normalize(barcode) {
  return String(barcode).trim().replace(/[\s-]/g, '');
}

function parseBarcode(barcode) {
  const cleaned = normalize(barcode);
  if (!/^\d{12}$/.test(cleaned)) {
    // Anything that is not exactly twelve digits cannot carry a UPC-A checksum.
    throw new Error(`invalid barcode: ${cleaned || '(empty)'}`);
  }
  return cleaned.split('').map(Number);
}

// Takes the eleven payload digits and returns the digit that should follow.
function computeCheckDigit(payload) {
  let oddSum = 0;
  let evenSum = 0;
  for (let i = 0; i < payload.length; i++) {
    // Position 1 is the first digit, so even array indices are odd positions.
    if (i % 2 === 0) {
      oddSum += payload[i];
    } else {
      evenSum += payload[i];
    }
  }
  const remainder = (oddSum * 3 + evenSum) % 10;
  // A remainder of zero means the check digit is zero, not ten.
  return remainder === 0 ? 0 : 10 - remainder;
}

function scan(barcode) {
  const digits = parseBarcode(barcode);
  const payload = digits.slice(0, 11);
  const printed = digits[11];
  return computeCheckDigit(payload) === printed ? 'match' : 'mismatch';
}

// Human-readable line for a scan log: code, verdict and the expected digit.
function describe(barcode) {
  const digits = parseBarcode(barcode);
  const expected = computeCheckDigit(digits.slice(0, 11));
  const verdict = scan(barcode);
  return `${digits.join('')} -> ${verdict} (expected check digit ${expected})`;
}

function main() {
  const samples = [
    '036000291452',
    '0 36000 29145 2',
    '036000291453',
    '12345678901',
  ];
  for (const sample of samples) {
    try {
      console.log(describe(sample));
    } catch (err) {
      // Malformed entries are reported but must not stop the rest of the batch.
      console.log(`${sample} -> error: ${err.message}`);
    }
  }
}

// Run the driver only when this file is executed directly.
if (require.main === module) {
  main();
}

module.exports = { scan, computeCheckDigit, parseBarcode, describe };

