const RATE_PER_MILE = 0.2;
const PEAK_SURCHARGE = 15;
const FIRST_CLASS_MULTIPLIER = 1.5;

// The four fields always arrive in the same positional order
const FIELDS = ['miles', 'age', 'peak', 'firstClass'];

function parseDetails(details) {
  if (!Array.isArray(details) || details.length !== FIELDS.length) {
    throw new TypeError('details must be a list of four numbers');
  }
  const record = {};
  FIELDS.forEach((name, index) => {
    const value = details[index];
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      throw new TypeError(`${name} must be a finite number`);
    }
    record[name] = value;
  });
  // the last two fields are binary flags, so anything else is a caller mistake
  if (record.peak !== 0 && record.peak !== 1) {
    throw new RangeError('peak flag must be 0 or 1');
  }
  if (record.firstClass !== 0 && record.firstClass !== 1) {
    throw new RangeError('first class flag must be 0 or 1');
  }
  return record;
}

// Children travel at half price, seniors keep 70% of the base fare
function ageDiscount(age) {
  if (age < 12) {
    return 0.5;
  }
  if (age >= 65) {
    return 0.3;
  }
  return 0;
}

function price(details) {
  const { miles, age, peak, firstClass } = parseDetails(details);
  let fare = miles * RATE_PER_MILE;
  // the discount applies to the base fare only, before any surcharge
  fare -= fare * ageDiscount(age);
  if (peak === 1) {
    fare += PEAK_SURCHARGE;
  }
  if (firstClass === 1) {
    // first class scales everything accumulated so far, surcharge included
    fare *= FIRST_CLASS_MULTIPLIER;
  }
  return Math.floor(fare);
}

function describe(details) {
  const { miles, age, peak, firstClass } = parseDetails(details);
  const timeLabel = peak === 1 ? 'peak' : 'off peak';
  const classLabel = firstClass === 1 ? 'first class' : 'standard class';
  // a single human readable line per ticket for the report below
  return `${miles} mi, age ${age}, ${timeLabel}, ${classLabel}: ${price(details)}`;
}

function main() {
  const tickets = [
    [100, 10, 0, 0],
    [100, 10, 1, 0],
    [250, 70, 0, 1],
    [42, 30, 1, 1],
  ];
  tickets.forEach((ticket) => console.log(describe(ticket)));
  // the fleet total is what the ticket office actually reports at closing
  const total = tickets.reduce((sum, ticket) => sum + price(ticket), 0);
  console.log(`Total collected: ${total}`);
}

main();

module.exports = { price, describe };

