// Aquarium filter sizing: turnover-based flow rate recommendation.

const CUBIC_INCHES_PER_GALLON = 231;
const BASE_TURNOVER_PER_HOUR = 4;

// Bioload multipliers: 1 = light, 2 = moderate population, 3 = heavy/messy eaters.
const BIOLOAD_MULTIPLIERS = { 1: 1, 2: 1.5, 3: 2 };

const DEAD_ZONE_THRESHOLD_GALLONS = 50;
const DEAD_ZONE_BONUS_GPH = 50;

function parseParameters(parameters) {
  if (!Array.isArray(parameters) || parameters.length !== 4) {
    throw new TypeError('size() expects [length, width, height, bioload]');
  }
  const [length, width, height, bioload] = parameters.map(Number);
  // Non-finite entries mean the caller passed text or nothing at all.
  if (![length, width, height, bioload].every(Number.isFinite)) {
    throw new TypeError('All parameters must be numbers');
  }
  if (length <= 0 || width <= 0 || height <= 0) {
    throw new RangeError('Tank dimensions must be positive inches');
  }
  if (!Object.prototype.hasOwnProperty.call(BIOLOAD_MULTIPLIERS, String(bioload))) {
    throw new RangeError('Bioload rating must be 1, 2 or 3');
  }
  return { length, width, height, bioload };
}

// Tanks are sold and stocked in whole gallons, so the gross volume is reported that way.
function grossVolume(length, width, height) {
  return Math.round((length * width * height) / CUBIC_INCHES_PER_GALLON);
}

function size(parameters) {
  const { length, width, height, bioload } = parseParameters(parameters);
  const volume = grossVolume(length, width, height);
  let flow = BASE_TURNOVER_PER_HOUR * volume;
  // Heavier stocking needs more passes through the media each hour.
  flow *= BIOLOAD_MULTIPLIERS[bioload];
  if (volume > DEAD_ZONE_THRESHOLD_GALLONS) {
    // Large footprints develop dead spots, so overshoot the pump rating.
    flow += DEAD_ZONE_BONUS_GPH;
  }
  return Math.round(flow);
}

function describe(parameters) {
  const [length, width, height, bioload] = parameters;
  const volume = grossVolume(length, width, height);
  const gph = size(parameters);
  // Report the turnover actually achieved, which is what filter boxes advertise.
  const turnover = (gph / volume).toFixed(1);
  return `${length}x${width}x${height}in, bioload ${bioload}: ${volume} gal -> ${gph} gph (${turnover}x/hr)`;
}

function main() {
  const tanks = [
    [20, 10, 12, 1],
    [30, 12, 16, 2],
    [48, 18, 21, 3],
  ];
  for (const tank of tanks) {
    console.log(describe(tank));
  }
  try {
    size([24, 12, 16, 4]);
  } catch (err) {
    // Bad stocking ratings are a user error, not a crash.
    console.log(`rejected: ${err.message}`);
  }
}

main();

module.exports = { size, describe, grossVolume };

