// Ski pass pricing: daily rates depend on age, with a holiday surcharge and
// a discount for multi-day passes.

const ADULT_RATE = 120;
const CHILD_RATE = 60;
const SENIOR_RATE = 90;
const HOLIDAY_FEE = 30;
const DISCOUNT_DAYS = 3;
const DISCOUNT_RATE = 0.2;

function dailyRate(age) {
  // Children and seniors get their own rates; the boundaries are inclusive.
  if (age <= 12) return CHILD_RATE;
  if (age >= 65) return SENIOR_RATE;
  return ADULT_RATE;
}

function parseTraveler(traveler) {
  if (!Array.isArray(traveler) || traveler.length < 3) {
    throw new TypeError('traveler must be [age, days, holidayFlag]');
  }
  const [age, days, holiday] = traveler;
  if (!Number.isFinite(age) || age < 0) {
    throw new RangeError(`invalid age: ${age}`);
  }
  // Days must be a whole positive number, since a pass is sold per full day.
  if (!Number.isInteger(days) || days < 1) {
    throw new RangeError(`invalid day count: ${days}`);
  }
  return { age, days, holiday: Boolean(holiday) };
}

function charge(traveler) {
  const { age, days, holiday } = parseTraveler(traveler);
  // The blackout fee is folded into the per-day price, so the discount applies to it too.
  const perDay = dailyRate(age) + (holiday ? HOLIDAY_FEE : 0);
  let total = perDay * days;
  if (days >= DISCOUNT_DAYS) {
    total *= 1 - DISCOUNT_RATE;
  }
  // Partial currency units are never charged: always round down.
  return Math.floor(total);
}

function describe(traveler) {
  const { age, days, holiday } = parseTraveler(traveler);
  const season = holiday ? 'holiday' : 'regular';
  const bracket = age <= 12 ? 'child' : age >= 65 ? 'senior' : 'adult';
  return `${bracket} (${age}), ${days} day(s), ${season}: $${charge(traveler)}`;
}

function groupTotal(party) {
  // A family or group simply pays the sum of the individual passes.
  return party.reduce((sum, traveler) => sum + charge(traveler), 0);
}

function main() {
  const party = [
    [10, 3, false],
    [37, 2, true],
    [68, 5, true],
  ];
  for (const traveler of party) {
    console.log(describe(traveler));
  }
  // Report the combined cost so the group can settle up at the window.
  console.log(`group total: $${groupTotal(party)}`);
}

module.exports = { charge, dailyRate, describe, groupTotal };

// Only run the driver when this file is executed directly, not when required.
if (require.main === module) {
  main();
}

