// Elo-style rating calculator: expected score, development coefficient and new rating.

// A match is [playerRating, opponentRating, outcome, previousGames].
function parseMatch(match) {
  if (!Array.isArray(match) || match.length !== 4) {
    throw new TypeError('A match must be an array of four numbers');
  }
  const [player, opponent, outcome, games] = match.map(Number);
  // Non-numeric entries would silently poison the arithmetic below.
  if ([player, opponent, outcome, games].some((n) => !Number.isFinite(n))) {
    throw new TypeError('Match entries must be finite numbers');
  }
  if (outcome !== 0 && outcome !== 0.5 && outcome !== 1) {
    throw new RangeError('Outcome must be 1 (win), 0.5 (draw) or 0 (loss)');
  }
  // A game count cannot be negative or fractional.
  if (games < 0 || !Number.isInteger(games)) {
    throw new RangeError('Previous games must be a non-negative integer');
  }
  return { player, opponent, outcome, games };
}

// Logistic expectation: a 400-point gap corresponds to ten-to-one odds.
function expectedScore(player, opponent) {
  return 1 / (1 + Math.pow(10, (opponent - player) / 400));
}

function developmentCoefficient(rating, games) {
  // Newcomers move fast so their rating converges quickly.
  if (games < 30) return 40;
  // Experienced players below the master threshold still move at a medium pace.
  if (rating < 2400) return 20;
  return 10;
}

function rate(match) {
  const { player, opponent, outcome, games } = parseMatch(match);
  const expected = expectedScore(player, opponent);
  const k = developmentCoefficient(player, games);
  // The rating change rewards results that beat the expectation.
  const change = k * (outcome - expected);
  return Math.round(player + change);
}

// Human-readable line for one match, useful for a tournament report.
function describe(match) {
  const { player, opponent, outcome, games } = parseMatch(match);
  const expected = expectedScore(player, opponent);
  const k = developmentCoefficient(player, games);
  const result = outcome === 1 ? 'win' : outcome === 0.5 ? 'draw' : 'loss';
  const newRating = rate(match);
  const delta = newRating - player;
  // Show the sign explicitly so gains and losses are easy to scan.
  const signed = delta >= 0 ? `+${delta}` : `${delta}`;
  return `${player} vs ${opponent}: ${result} (expected ${expected.toFixed(3)}, ` +
    `K=${k}) -> ${newRating} (${signed})`;
}

function main() {
  const matches = [
    [1500, 1600, 1, 10],
    [1500, 1600, 0.5, 10],
    [2200, 2300, 0, 120],
    [2500, 2450, 1, 300],
  ];
  for (const match of matches) {
    console.log(describe(match));
  }
  // Sum the changes to check how much rating the group as a whole gained.
  const net = matches.reduce((acc, m) => acc + (rate(m) - m[0]), 0);
  console.log(`Net rating movement: ${net > 0 ? '+' : ''}${net}`);
}

main();

module.exports = { rate, expectedScore, developmentCoefficient, describe };

