const VALUES = { red: 1, yellow: 2, green: 3, brown: 4, blue: 5, pink: 6, black: 7 };

// Ball names are compared in a canonical form so " Black" and "black" behave alike
function normalize(name) {
  return typeof name === 'string' ? name.trim().toLowerCase() : '';
}

// Core scorer: walks the break and reports where it ended, which both public
// helpers below need
function scoreBreak(balls) {
  if (!Array.isArray(balls)) return { points: 0, potted: 0 };

  let points = 0;
  let potted = 0;
  let expectRed = true;      // during the red phase, pots alternate red / colour
  let clearance = false;     // true once the reds are exhausted
  let last = 0;              // value of the previous colour in the clearance

  for (const raw of balls) {
    const name = normalize(raw);
    const value = VALUES[name];

