// Battery health projection for lithium-ion packs.
// Degradation is modelled per charge cycle from depth of discharge and temperature.

const DEEP_DISCHARGE_PENALTY = 0.05;
const MEDIUM_DISCHARGE_PENALTY = 0.02;
const SHALLOW_DISCHARGE_PENALTY = 0.01;

// Threshold above which heat accelerates electrolyte breakdown.
const HOT_CYCLE_CELSIUS = 35;

function cyclePenalty(depthOfDischarge, temperature) {
  let penalty;
  if (depthOfDischarge > 80) {
    penalty = DEEP_DISCHARGE_PENALTY;
  } else if (depthOfDischarge >= 50) {
    // The 50-80 band is inclusive at both ends.
    penalty = MEDIUM_DISCHARGE_PENALTY;
  } else {
    penalty = SHALLOW_DISCHARGE_PENALTY;
  }
  if (temperature > HOT_CYCLE_CELSIUS) {
    penalty *= 2; // Hot cycles wear the cell twice as fast.
  }
  return penalty;
}

function readCycle(cycle, index) {
  // Accept either named fields or the shorthand [dod, temp] pair.
  const dod = Array.isArray(cycle) ? cycle[0] : cycle.depthOfDischarge ?? cycle.dod;
  const temp = Array.isArray(cycle) ? cycle[1] : cycle.temperature ?? cycle.temp;
  if (typeof dod !== 'number' || Number.isNaN(dod)) {
    throw new TypeError(`cycle ${index}: depth of discharge must be a number`);
  }
  if (typeof temp !== 'number' || Number.isNaN(temp)) {
    throw new TypeError(`cycle ${index}: temperature must be a number`);
  }
  return { dod, temp };
}

function estimate(usage) {
  if (!Array.isArray(usage)) {
    throw new TypeError('usage must be an array of charge cycles');
  }
  let health = 100;
  usage.forEach((cycle, index) => {
    const { dod, temp } = readCycle(cycle, index);
    health -= cyclePenalty(dod, temp);
  });
  // Round to one decimal, guarding against binary floating point drift.
  return Math.round(health * 10) / 10;
}

function report(label, usage) {
  const health = estimate(usage);
  // A pack below eighty percent is conventionally considered end-of-life.
  const verdict = health < 80 ? 'replace' : 'serviceable';
  return `${label}: ${health.toFixed(1)}% (${verdict})`;
}

function main() {
  const commuterPack = [];
  for (let day = 0; day < 500; day += 1) {
    // Weekday commute drains about 60%, weekends barely touch the pack.
    const weekend = day % 7 >= 5;
    commuterPack.push({ depthOfDischarge: weekend ? 20 : 60, temperature: 24 });
  }
  const desertFleet = [
    { depthOfDischarge: 95, temperature: 41 },
    { depthOfDischarge: 90, temperature: 38 },
    { depthOfDischarge: 45, temperature: 30 },
  ];
  console.log(report('commuter pack', commuterPack));
  console.log(report('desert fleet', desertFleet));
  // Shorthand pairs are handled too, for logs exported as CSV rows.
  console.log(report('bench cell', [[100, 36], [100, 20]]));
}

main();

module.exports = { estimate, cyclePenalty, report };

