const ROLE_WEIGHTS = {
  bartender: 2,
  server: 1.5,
  busser: 1,
  host: 0.5
};

// Roles are matched case-insensitively and tolerate stray whitespace in the records
function weightFor(role) {
  const key = String(role).trim().toLowerCase();
  if (!Object.prototype.hasOwnProperty.call(ROLE_WEIGHTS, key)) {
    throw new Error(`Unknown role: ${role}`);
  }
  return ROLE_WEIGHTS[key];
}

// Hours may arrive as strings from a timesheet export, so coerce and sanity-check them
function hoursFor(employee) {
  const hours = Number(employee.hours);
  if (!Number.isFinite(hours) || hours < 0) {
    throw new Error(`Invalid hours for ${employee.name}: ${employee.hours}`);
  }
  return hours;
}

function pointsFor(employee) {
  return weightFor(employee.role) * hoursFor(employee);
}

function roundCents(amount) {
  // Scale, round, and rescale so the returned value is a clean number of cents
  return Math.round(amount * 100) / 100;
}

function distribute(shift) {
  const totalTips = Number(shift.totalTips);
  if (!Number.isFinite(totalTips) || totalTips < 0) {
    throw new Error(`Invalid tip total: ${shift.totalTips}`);
  }
  const staff = shift.employees || [];
  const points = staff.map(pointsFor);
  const totalPoints = points.reduce((sum, p) => sum + p, 0);
  // Nobody logged weighted hours, so there is no defensible way to split the pool
  if (totalPoints === 0) {
    return staff.map((employee) => ({ name: employee.name, tip: 0 }));
  }
  const dollarsPerPoint = totalTips / totalPoints;
  return staff.map((employee, i) => ({
    name: employee.name,
    tip: roundCents(points[i] * dollarsPerPoint)
  }));
}

function formatReport(shares) {
  // Pad names to the longest one so the dollar column lines up in the printout
  const width = shares.reduce((max, s) => Math.max(max, s.name.length), 0);
  const lines = shares.map(
    (s) => `${s.name.padEnd(width)}  $${s.tip.toFixed(2).padStart(8)}`
  );
  const paidOut = shares.reduce((sum, s) => sum + s.tip, 0);
  lines.push(`${'TOTAL'.padEnd(width)}  $${paidOut.toFixed(2).padStart(8)}`);
  return lines.join('\n');
}

function main() {
  const shift = {
    totalTips: 1240.75,
    employees: [
      { name: 'Alice', role: 'Bartender', hours: 8 },
      { name: 'Bao', role: 'bartender', hours: 6.5 },
      { name: 'Carmen', role: 'Server', hours: 8 },
      { name: 'Dmitri', role: 'server', hours: 7.25 },
      { name: 'Efua', role: 'Busser', hours: 6 },
      { name: 'Farid', role: 'Host', hours: 5 }
    ]
  };
  const shares = distribute(shift);
  console.log(formatReport(shares));
  // Rounding each share independently can leave the payout a cent or two off the pool
  const drift = roundCents(shares.reduce((s, x) => s + x.tip, 0) - shift.totalTips);
  if (drift !== 0) {
    console.log(`Rounding drift versus pool: $${drift.toFixed(2)}`);
  }
}

main();

module.exports = { distribute, formatReport };

