//  Tinseth-style IBU estimator for a homebrew batch.

//  Gravity factor: hop utilization drops as the wort gets denser.
function bignessFactor(originalGravity) {
  return 1.65 * Math.pow(0.000125, originalGravity - 1);
}

//  Boil time factor: utilization rises toward an asymptote as the boil runs longer.
function boilTimeFactor(minutes) {
  return (1 - Math.exp(-0.04 * minutes)) / 4.15;
}

function utilization(minutes, originalGravity) {
  return bignessFactor(originalGravity) * boilTimeFactor(minutes);
}

//  A single addition contributes weight * alpha% * utilization * 10 / volume.
function additionIbu(hop, volumeLiters, originalGravity) {
  const u = utilization(hop.time, originalGravity);
  return (hop.weight * hop.alpha * u * 10) / volumeLiters;
}

function validateRecipe(recipe) {
  if (!recipe || typeof recipe !== 'object') {
    throw new TypeError('recipe must be an object');
  }
  //  A zero or missing volume would make every addition divide by zero.
  if (!(recipe.volume > 0)) {
    throw new RangeError('volume must be a positive number of liters');
  }
  //  Gravity below 1.000 is lighter than water and has no physical meaning here.
  if (!(recipe.gravity >= 1)) {
    throw new RangeError('gravity must be at least 1.000');
  }
  const hops = recipe.hops || [];
  if (!Array.isArray(hops)) {
    throw new TypeError('hops must be an array of additions');
  }
  return hops;
}

function bitterness(recipe) {
  const hops = validateRecipe(recipe);
  const total = hops.reduce(
