const GAUGE_EPSILON = 1e-9;

// A gauge of zero or below would make the multiplier meaningless or infinite
function validateGauge(value, label) {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new TypeError(`${label} must be a finite number`);
  }
  if (value <= GAUGE_EPSILON) {
    throw new RangeError(`${label} must be greater than zero`);
  }
  return value;
}

// Only instructions carrying a usable stitch count get rescaled
function hasStitchCount(instruction) {
  return typeof instruction.count === 'number' && Number.isFinite(instruction.count);
}

function scaleCount(count, multiplier) {
  const scaled = count * multiplier;
  // Math.round biases negatives upward, so scale the magnitude and restore the sign
  const rounded = Math.sign(scaled) * Math.round(Math.abs(scaled));
  return rounded;
}

function scale(pattern) {
  if (pattern === null || typeof pattern !== 'object') {
    throw new TypeError('pattern must be an object');
  }
  const originalGauge = validateGauge(pattern.originalGauge, 'originalGauge');
  const newGauge = validateGauge(pattern.newGauge, 'newGauge');
  const instructions = pattern.instructions;
  if (!Array.isArray(instructions)) {
    throw new TypeError('pattern.instructions must be an array');
  }

  const multiplier = newGauge / originalGauge;

  return instructions.map((instruction) => {
    if (instruction === null || typeof instruction !== 'object') {
      throw new TypeError('each instruction must be an object');
    }
    // Copy first so untouched fields such as notes or repeats survive the scaling
    const next = { ...instruction };
    if (hasStitchCount(instruction)) {
      next.count = scaleCount(instruction.count, multiplier);
    }
    return next;
  });
}

// Renders one instruction the way a printed pattern line would read
function formatInstruction(instruction) {
  if (!hasStitchCount(instruction)) {
    return instruction.action;
  }
  const unit = Math.abs(instruction.count) === 1 ? 'stitch' : 'stitches';
  return `${instruction.action} ${instruction.count} ${unit}`;
}

function formatPattern(instructions) {
  return instructions.map((instruction, index) => `${index + 1}. ${formatInstruction(instruction)}`).join('\n');
}

function main() {
  const pattern = {
    originalGauge: 5,
    newGauge: 7,
    instructions: [
      { action: 'cast on', count: 30 },
      { action: 'knit', count: 15 },
      // Binding off works on whatever is on the needle, so it needs no count
      { action: 'bind off' },
      { action: 'purl', count: 4 },
      { action: 'weave in ends' },
    ],
  };

  const scaled = scale(pattern);
  console.log(`Regauged from ${pattern.originalGauge} to ${pattern.newGauge} stitches per inch:`);
  console.log(formatPattern(scaled));
}

main();

module.exports = { scale, formatInstruction, formatPattern };

