const G = 9.80665;

// Convert litres per second to cubic metres per second, the SI unit the formulae expect
function toCubicMetresPerSecond(litresPerSecond) {
  return litresPerSecond / 1000;
}

// Diameters are given in millimetres, so scale them down to metres
function toMetres(millimetres) {
  return millimetres / 1000;
}

function crossSectionArea(diameterMm) {
  const d = toMetres(diameterMm);
  return (Math.PI * d * d) / 4;
}

// Velocity follows from continuity: Q = A * v
function velocity(segment) {
  return toCubicMetresPerSecond(segment.flow) / crossSectionArea(segment.diameter);
}

// Darcy-Weisbach: h = f * (L / D) * v^2 / (2g)
function headLoss(segment) {
  const v = velocity(segment);
  return segment.friction * (segment.length / toMetres(segment.diameter)) * ((v * v) / (2 * G));
}

function validate(segment, index) {
  const required = ['flow', 'diameter', 'length', 'friction'];
  for (const key of required) {
    if (typeof segment[key] !== 'number' || Number.isNaN(segment[key])) {
      throw new TypeError(`segment ${index}: "${key}" must be a number`);
    }
  }
  // A zero or negative diameter would make the area vanish and the velocity blow up
  if (segment.diameter <= 0) {
    throw new RangeError(`segment ${index}: diameter must be positive`);
  }
  if (segment.length < 0 || segment.friction < 0) {
    throw new RangeError(`segment ${index}: length and friction must be non-negative`);
  }
}

function loss(system) {
  if (!Array.isArray(system)) {
    throw new TypeError('system must be an array of pipe segments');
  }
  let total = 0;
  system.forEach((segment, index) => {
    validate(segment, index);
    total += headLoss(segment);
  });
  // The task asks for three decimal places on the accumulated loss only
  return Math.round(total * 1000) / 1000;
}

// Per-segment breakdown, useful when sizing a pump for the whole network
function report(system) {
  const lines = system.map((segment, index) => {
    const v = velocity(segment).toFixed(3);
    const h = headLoss(segment).toFixed(3);
    return `#${index + 1}  DN${segment.diameter}  ${segment.length} m  v=${v} m/s  h=${h} m`;
  });
  lines.push(`total head loss: ${loss(system).toFixed(3)} m`);
  return lines.join('\n');
}

const network = [
  { flow: 12.5, diameter: 100, length: 45, friction: 0.021 },
  { flow: 8.0, diameter: 80, length: 30, friction: 0.023 },
  { flow: 4.5, diameter: 50, length: 12.5, friction: 0.026 },
];

console.log(report(network));

module.exports = { loss, headLoss, velocity, report };

