// Nutrient concentrations (by mass) of the available raw materials.
const UREA_N = 0.46;
const DAP_N = 0.18;
const DAP_P = 0.46;
const MOP_K = 0.60;

// Percentages are accepted as whole numbers (e.g. 12 for 12%).
function validate(requirements) {
  const { mass, nitrogen, phosphorus, potassium } = requirements;
  if (!(mass > 0)) {
    throw new RangeError('target mass must be a positive number of kilograms');
  }
  for (const [name, pct] of [['nitrogen', nitrogen], ['phosphorus', phosphorus], ['potassium', potassium]]) {
    // A nutrient share outside 0..100 cannot describe a real blend.
    if (!(pct >= 0 && pct <= 100)) {
      throw new RangeError(`${name} percentage must lie between 0 and 100`);
    }
  }
  return { mass, nitrogen, phosphorus, potassium };
}

function blend(requirements) {
  const { mass, nitrogen, phosphorus, potassium } = validate(requirements);

  // Step 1: convert the target percentages into nutrient masses.
  const needN = mass * nitrogen / 100;
  const needP = mass * phosphorus / 100;
  const needK = mass * potassium / 100;

  // Step 2: phosphorus is only available from diammonium phosphate.
  const dap = needP / DAP_P;

  // Step 3: the DAP already supplies part of the nitrogen demand.
  const nFromDap = dap * DAP_N;
  const remainingN = needN - nFromDap;
  if (remainingN < 0) {
    // No material removes nitrogen, so the recipe is impossible as stated.
    throw new RangeError('phosphorus target forces more nitrogen than requested');
  }
  const urea = remainingN / UREA_N;

  // Step 4: potassium comes entirely from muriate of potash.
  const potash = needK / MOP_K;

  // Step 5: inert filler tops the mixture up to the requested mass.
  const filler = mass - (urea + dap + potash);
  if (filler < 0) {
    throw new RangeError('nutrient targets are too concentrated for the available materials');
  }
  return [urea, dap, potash, filler];
}

// Renders a blend as a human readable batch sheet.
function formatRecipe(mass, amounts) {
  const labels = ['urea', 'diammonium phosphate', 'muriate of potash', 'inert filler'];
  const lines = amounts.map((kg, i) => {
    const share = 100 * kg / mass;
    return `  ${labels[i].padEnd(22)} ${kg.toFixed(2).padStart(8)} kg  (${share.toFixed(1)}%)`;
  });
  return lines.join('\n');
}

function main() {
  // A common 10-10-10 garden grade, mixed as a one tonne batch.
  const order = { mass: 1000, nitrogen: 10, phosphorus: 10, potassium: 10 };
  const amounts = blend(order);
  console.log(`Batch of ${order.mass} kg (${order.nitrogen}-${order.phosphorus}-${order.potassium}):`);
  console.log(formatRecipe(order.mass, amounts));

  // A high phosphorus starter fertilizer needs no extra urea at all.
  const starter = { mass: 50, nitrogen: 18, phosphorus: 46, potassium: 0 };
  console.log(`\nBatch of ${starter.mass} kg (18-46-0):`);
  console.log(formatRecipe(starter.mass, blend(starter)));
}

main();

module.exports = { blend, formatRecipe };

