const DENSITY = { cement: 1440, sand: 1600, gravel: 1500 };

// Mix designs keyed by the compressive strength they are meant to reach (MPa)
const MIXES = {
  20: { parts: { cement: 1, sand: 2, gravel: 4 }, waterRatio: 0.5 },
  30: { parts: { cement: 1, sand: 1.5, gravel: 3 }, waterRatio: 0.45 },
};

function mix(volume, strength = 20) {
  if (!Number.isFinite(volume) || volume <= 0) {
    throw new RangeError(`volume must be a positive number of cubic metres, got ${volume}`);
  }
  const design = MIXES[strength];
  // Only the two tabulated designs are defined; anything else would need interpolation
  if (!design) {
    throw new RangeError(`no mix design for ${strength} MPa (available: ${Object.keys(MIXES).join(', ')})`);
  }

  const { parts, waterRatio } = design;
  const totalParts = parts.cement + parts.sand + parts.gravel;

  // Each dry component occupies its share of the target volume, then is weighed via its density
  const cement = (volume * parts.cement / totalParts) * DENSITY.cement;
  const sand = (volume * parts.sand / totalParts) * DENSITY.sand;
  const gravel = (volume * parts.gravel / totalParts) * DENSITY.gravel;

  // Water is dosed against the cement *weight*, not against the batch volume
  const water = cement * waterRatio;

  return { cement, sand, gravel, water };
}

function totalWeight(batch) {
  return Object.values(batch).reduce((sum, kg) => sum + kg, 0);
}

function bagsOfCement(batch, bagWeight = 50) {
  // Cement is sold in whole bags, so a partial bag has to be rounded up
  return Math.ceil(batch.cement / bagWeight);
}

function formatBatch(batch) {
  const order = ['cement', 'sand', 'gravel', 'water'];
  const lines = order.map((name) => {
    const label = name.padEnd(7, ' ');
    // Kilogram figures below one decimal place are meaningless on a site scale
    return `  ${label}${batch[name].toFixed(1).padStart(9, ' ')} kg`;
  });
  return lines.join('\n');
}

function report(volume, strength) {
  const batch = mix(volume, strength);
  const header = `${volume} m3 of concrete at ${strength} MPa`;
  const footer = [
    `  total  ${totalWeight(batch).toFixed(1).padStart(9, ' ')} kg`,
    `  cement bags (50 kg): ${bagsOfCement(batch)}`,
  ].join('\n');
  return [header, formatBatch(batch), footer].join('\n');
}

function main() {
  // Two representative pours: a small slab and a stronger structural element
  console.log(report(1, 20));
  console.log(report(2.5, 30));

  try {
    report(1, 40);
  } catch (err) {
    // Reported rather than rethrown so the driver still exits cleanly
    console.log(`rejected: ${err.message}`);
  }
}

main();

module.exports = { mix, totalWeight, bagsOfCement, formatBatch, report };

