const MULTIPLIERS = {
  normal: 2.0,
  large: 1.8,
};

const BASE_POINTS = 60;
const MAX_MARK = 20;

// A jump is only scoreable if the hill category maps to a known multiplier.
function distanceMultiplier(hillSize) {
  const key = String(hillSize).trim().toLowerCase();
  if (!(key in MULTIPLIERS)) {
    throw new Error(`unknown hill size: ${hillSize}`);
  }
  return MULTIPLIERS[key];
}

function validate(jump) {
  const { distance, kPoint, styleMarks } = jump;
  // Distance and k-point drive the whole calculation, so they must be real numbers.
  if (!Number.isFinite(distance) || !Number.isFinite(kPoint)) {
    throw new Error('distance and kPoint must be finite numbers');
  }
  if (!Array.isArray(styleMarks) || styleMarks.length !== 5) {
    throw new Error('exactly five style marks are required');
  }
  for (const mark of styleMarks) {
    // Judges score out of twenty; anything outside that range is a data error.
    if (!Number.isFinite(mark) || mark < 0 || mark > MAX_MARK) {
      throw new Error(`style mark out of range: ${mark}`);
    }
  }
}

function distancePoints(distance, kPoint, hillSize) {
  const metresPastK = distance - kPoint;
  // Landing short of the k-point subtracts points, because the difference is negative.
  return BASE_POINTS + metresPastK * distanceMultiplier(hillSize);
}

function stylePoints(styleMarks) {
  const sorted = [...styleMarks].sort((a, b) => a - b);
  // Drop the extreme marks at both ends and keep the middle three.
  const kept = sorted.slice(1, -1);
  return kept.reduce((total, mark) => total + mark, 0);
}

function score(jump) {
  validate(jump);
  const points =
    distancePoints(jump.distance, jump.kPoint, jump.hillSize) +
    stylePoints(jump.styleMarks);
  // Floating point multiplication by 1.8 leaves noise, so settle on one decimal.
  return Math.round(points * 10) / 10;
}

function report(jumps) {
  return jumps
    .map((jump) => ({ jump, total: score(jump) }))
    // Highest total first, which is the order used on a competition scoreboard.
    .sort((a, b) => b.total - a.total)
    .map(({ jump, total }, index) =>
      `${index + 1}. ${jump.name}: ${jump.distance}m on a ${jump.hillSize} hill - ${total.toFixed(1)}`
    );
}

const competition = [
  { name: 'Kobayashi', distance: 99.5, kPoint: 98, hillSize: 'normal', styleMarks: [19, 19.5, 19, 19.5, 19] },
  { name: 'Granerud', distance: 131, kPoint: 125, hillSize: 'large', styleMarks: [18, 18.5, 19, 18, 18.5] },
  { name: 'Stoch', distance: 121.5, kPoint: 125, hillSize: 'large', styleMarks: [18.5, 18, 18.5, 19, 18] },
];

for (const line of report(competition)) {
  console.log(line);
}

module.exports = { score, distancePoints, stylePoints, report };

