// Brewing helper: compute the strike water temperature needed to hit a mash target.
//
// Strike temp = target + (0.41 / (liters per kg)) * (target - grain temp)

const GRAIN_CONSTANT = 0.41;

// Round to one decimal place without the floating point noise of toFixed on halves.
function roundTenth(value) {
  return Math.round((value + Number.EPSILON) * 10) / 10;
}

function validateMash(mash) {
  if (mash === null || typeof mash !== 'object') {
    throw new TypeError('mash must be an object describing the mash');
  }
  const fields = ['target', 'grainWeight', 'waterVolume', 'grainTemp'];
  for (const field of fields) {
    // Every field is a physical measurement, so it has to be a finite number.
    if (!Number.isFinite(mash[field])) {
      throw new TypeError(`mash.${field} must be a finite number`);
    }
  }
  // Both of these end up in a division, so zero or negative values are meaningless.
  if (mash.grainWeight <= 0) {
    throw new RangeError('mash.grainWeight must be greater than zero');
  }
  if (mash.waterVolume <= 0) {
    throw new RangeError('mash.waterVolume must be greater than zero');
  }
  return mash;
}

// Liters of strike water per kilogram of crushed grain: the thermal mass ratio.
function thermalMassRatio(mash) {
  return mash.waterVolume / mash.grainWeight;
}

function temperatureDifferential(mash) {
  const ratio = thermalMassRatio(mash);
  // A thinner mash (larger ratio) needs a smaller boost above the target.
  return (GRAIN_CONSTANT / ratio) * (mash.target - mash.grainTemp);
}

function temperature(mash) {
  validateMash(mash);
  const strike = mash.target + temperatureDifferential(mash);
  return roundTenth(strike);
}

// Human readable summary of one mash, used by the driver below.
function describe(mash) {
  const ratio = roundTenth(thermalMassRatio(mash));
  const strike = temperature(mash);
  return `${mash.grainWeight} kg grain @ ${mash.grainTemp} C + ${mash.waterVolume} L water ` +
    `(${ratio} L/kg) -> mash ${mash.target} C needs strike water at ${strike} C`;
}

const recipes = [
  { target: 67, grainWeight: 5, waterVolume: 15, grainTemp: 20 },
  { target: 68, grainWeight: 4.5, waterVolume: 13.5, grainTemp: 18 },
  // Winter brew day: cold grain forces a much hotter strike.
  { target: 66.5, grainWeight: 6, waterVolume: 12, grainTemp: 4 },
];

for (const recipe of recipes) {
  console.log(describe(recipe));
}

// Guard against a recipe with a typo before the kettle is even heated.
try {
  temperature({ target: 67, grainWeight: 0, waterVolume: 15, grainTemp: 20 });
} catch (err) {
  console.log(`rejected recipe: ${err.message}`);
}

module.exports = { temperature, thermalMassRatio, temperatureDifferential, describe };

