const JULIAN_OFFSET = 1720994.5;
const GREGORIAN_ADOPTION = [1582, 10, 15];
const MONTH_LENGTHS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

// Lexicographic comparison of [year, month, day] triples
function compareDates(a, b) {
  for (let i = 0; i < 3; i += 1) {
    if (a[i] !== b[i]) return a[i] - b[i];
  }
  return 0;
}

function isLeapYear(year) {
  // Dates predating the Gregorian reform follow the plain Julian rule
  if (year < GREGORIAN_ADOPTION[0]) return year % 4 === 0;
  return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
}

function daysInMonth(year, month) {
  if (month === 2 && isLeapYear(year)) return 29;
  return MONTH_LENGTHS[month - 1];
}

function validateDate(date) {
  if (!Array.isArray(date) || date.length !== 3) {
    throw new TypeError('date must be a three element array [year, month, day]');
  }
  const [year, month, day] = date;
  if (!date.every(Number.isInteger)) {
    throw new TypeError('year, month and day must all be integers');
  }
  if (month < 1 || month > 12) {
    throw new RangeError(`month ${month} is out of range`);
  }
  // The month is known good here, so the length lookup is safe
  if (day < 1 || day > daysInMonth(year, month)) {
    throw new RangeError(`day ${day} is out of range for month ${month}`);
  }
}

function calculate(date) {
  validateDate(date);
  let [year, month] = date;
  const day = date[2];
  // January and February count as months 13 and 14 of the previous year
  if (month <= 2) {
    year -= 1;
    month += 12;
  }
  const century = Math.floor(year / 100);
  // Century term: the skipped leap days of the Gregorian calendar
  let total = Math.floor(century / 4) - century;
  total += Math.floor(365.25 * year);
  // Mean month length term, shifted so that March starts the cycle
  total += Math.floor(30.6001 * (month + 1));
  total += day;
  total += JULIAN_OFFSET;
  if (compareDates(date, GREGORIAN_ADOPTION) < 0) {
    // Before the reform no century correction applies, so undo it
    total += century - Math.floor(century / 4);
  }
  return total;
}

function formatDate([year, month, day]) {
  const pad = (n, width) => String(n).padStart(width, '0');
  return `${pad(year, 4)}-${pad(month, 2)}-${pad(day, 2)}`;
}

function report(dates) {
  // toFixed(1) keeps the trailing .5 visible for whole integral results
  return dates.map((d) => `${formatDate(d)} -> JD ${calculate(d).toFixed(1)}`);
}

function main() {
  const samples = [[2023, 10, 4], [2000, 1, 1], [1582, 10, 4], [1, 1, 1]];
  report(samples).forEach((line) => console.log(line));
}

main();

module.exports = { calculate, isLeapYear, daysInMonth, formatDate, report };

