const MAX_BITS_PER_SECOND = 320000;
const HEADER_BYTES = 44;
const BYTES_PER_MEGABYTE = 1048576;

// The four parameters must all be present and numeric before any arithmetic happens
function validate(parameters) {
  if (!Array.isArray(parameters) || parameters.length !== 4) {
    throw new TypeError('size() expects an array of exactly four numbers');
  }
  parameters.forEach((value, index) => {
    if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
      // index is reported so the caller can tell which field is wrong
      throw new RangeError(`parameter at index ${index} must be a finite, non-negative number`);
    }
  });
}

function size(parameters) {
  validate(parameters);
  const [duration, sampleRate, bitDepth, channels] = parameters;

  const sampleBits = bitDepth * channels;
  let bitsPerSecond = sampleBits * sampleRate;

  // Anything above the streaming ceiling is transparently re-encoded down to it
  if (bitsPerSecond > MAX_BITS_PER_SECOND) {
    bitsPerSecond = MAX_BITS_PER_SECOND;
  }

  const bytesPerSecond = bitsPerSecond / 8;
  const rawBytes = bytesPerSecond * duration;
  const totalBytes = rawBytes + HEADER_BYTES;

  const megabytes = totalBytes / BYTES_PER_MEGABYTE;
  // Two decimals is the precision used by the reporting layer below
  return Math.round(megabytes * 100) / 100;
}

// True when the requested bitrate had to be capped, which the report flags
function isCompressed(parameters) {
  const [, sampleRate, bitDepth, channels] = parameters;
  return bitDepth * channels * sampleRate > MAX_BITS_PER_SECOND;
}

function describe(parameters) {
  const [duration, sampleRate, bitDepth, channels] = parameters;
  const megabytes = size(parameters);
  const layout = channels === 1 ? 'mono' : channels === 2 ? 'stereo' : `${channels}-channel`;

  // Durations are shown as m:ss so long clips stay readable
  const minutes = Math.floor(duration / 60);
  const seconds = String(Math.round(duration % 60)).padStart(2, '0');

  const note = isCompressed(parameters) ? ' (compressed to 320 kbps)' : '';
  return `${minutes}:${seconds} ${layout} @ ${sampleRate} Hz / ${bitDepth}-bit -> ${megabytes.toFixed(2)} MB${note}`;
}

function main() {
  const clips = [
    [120, 44100, 16, 2],
    [30, 8000, 8, 1],
    [3600, 48000, 24, 6],
  ];

  clips.forEach((clip) => console.log(describe(clip)));

  // A single running total tells the user whether the batch fits on a device
  const totalMegabytes = clips.reduce((sum, clip) => sum + size(clip), 0);
  console.log(`total: ${totalMegabytes.toFixed(2)} MB`);
}

main();

module.exports = { size, describe, isCompressed };

