    const [thickness, width, length, density] = board;
    // Board footage is the lumber trade unit: inches x inches x feet / 12
    const boardFeet = (thickness * width * length) / 12;
    totalBoardFeet += boardFeet;
    // True volume converts both inch dimensions to feet, hence the 144 divisor
    const cubicFeet = (thickness * width * length) / 144;
    totalWeight += cubicFeet * density;
  });
