const STANDARD_DIAMETERS = [4, 6, 8, 10, 12, 14, 16, 18, 20, 24, 30, 36];

// available fan pressure in inches of water gauge, used as the pass/fail limit
const AVAILABLE_FAN_PRESSURE = 2.0;

function validateNetwork(network) {
  // the task fixes the input shape: volume, length, velocity
  if (!Array.isArray(network) || network.length !== 3) {
    throw new TypeError('network must be an array of three numbers');
  }
  const [volume, length, velocity] = network;
  for (const value of [volume, length, velocity]) {
    // NaN slips past typeof, so it has to be excluded explicitly
    if (typeof value !== 'number' || Number.isNaN(value)) {
      throw new TypeError('network entries must be numbers');
    }
  }
  // a zero velocity would make the required area infinite
  if (volume <= 0 || length <= 0 || velocity <= 0) {
    throw new RangeError('network entries must be positive');
  }
  return { volume, length, velocity };
}

function theoreticalDiameter(areaSquareInches) {
  // invert A = pi * d^2 / 4 to recover the diameter
  return Math.sqrt((4 * areaSquareInches) / Math.PI);
}

function standardDiameter(diameterInches) {
  // round up so the duct is never smaller than the airflow demands
  const fit = STANDARD_DIAMETERS.find((d) => d >= diameterInches);
  // beyond the largest catalogue size there is nothing to select
  return fit === undefined ? STANDARD_DIAMETERS[STANDARD_DIAMETERS.length - 1] : fit;
}

function frictionLossPer100ft(volume, diameterInches) {
  // empirical galvanized round duct friction equation (in. w.g. per 100 ft)
  return 0.109136 * Math.pow(volume, 1.9) / Math.pow(diameterInches, 5.02);
}

function size(network) {
  const { volume, length, velocity } = validateNetwork(network);
  const areaSquareFeet = volume / velocity;
  // duct catalogues and the friction equation both work in inches
  const areaSquareInches = areaSquareFeet * 144;
  const exactDiameter = theoreticalDiameter(areaSquareInches);
  const diameter = standardDiameter(exactDiameter);
  const lossPer100 = frictionLossPer100ft(volume, diameter);
  // scale the per-100-ft loss to the run actually installed
  const totalDrop = lossPer100 * (length / 100);
  if (totalDrop > AVAILABLE_FAN_PRESSURE) {
    // the fan cannot push this run: flag it instead of reporting a valid design
    return [diameter, totalDrop, true];
  }
  return [diameter, totalDrop];
}

function describe(name, network) {
  const [diameter, drop, failed] = size(network);
  const head = `${name}: ${diameter} in duct, ${drop.toFixed(3)} in. w.g.`;
  // the third slot is only present when the design overruns the fan
  return failed ? `${head} -- EXCEEDS FAN PRESSURE` : head;
}

const runs = [
  ['Main trunk', [1200, 60, 900]],
  ['Branch to office', [400, 45, 700]],
  ['Long undersized run', [2000, 250, 2500]],
];

for (const [name, network] of runs) {
  console.log(describe(name, network));
}

