// Karvonen-formula training-zone calculator.

// Standard constant used to estimate maximum heart rate from age.
const MAX_HR_BASE = 220;

// Zone boundaries are expressed as fractions of the heart rate reserve.
const ZONE_INTENSITIES = [0.5, 0.6, 0.7, 0.8, 0.9];

function validateAthlete(athlete) {
  if (!Array.isArray(athlete) || athlete.length !== 2) {
    throw new TypeError('athlete must be an array of [age, restingHeartRate]');
  }
  const [age, resting] = athlete;
  // Both entries must be usable numbers; strings and NaN are rejected outright.
  if (!Number.isFinite(age) || !Number.isFinite(resting)) {
    throw new TypeError('age and resting heart rate must be finite numbers');
  }
  if (age <= 0 || age >= MAX_HR_BASE) {
    throw new RangeError('age must lie between 0 and 220');
  }
  // A resting rate at or above the estimated maximum leaves no reserve to split.
  if (resting <= 0 || resting >= MAX_HR_BASE - age) {
    throw new RangeError('resting heart rate must be below the maximum heart rate');
  }
  return { age, resting };
}

function zones(athlete) {
  const { age, resting } = validateAthlete(athlete);
  const maxHeartRate = MAX_HR_BASE - age;
  const reserve = maxHeartRate - resting;
  // Each threshold is a share of the reserve added back onto the resting rate.
  return ZONE_INTENSITIES.map((intensity) => Math.round(resting + reserve * intensity));
}

function describeZones(athlete) {
  const thresholds = zones(athlete);
  const labels = ['Zone 1', 'Zone 2', 'Zone 3', 'Zone 4', 'Zone 5'];
  return thresholds.map((bpm, index) => {
    // The upper bound of a zone is the next threshold, or the maximum for zone 5.
    const upper = index + 1 < thresholds.length
      ? thresholds[index + 1]
      : MAX_HR_BASE - athlete[0];
    return `${labels[index]}: ${bpm}-${upper} bpm`;
  });
}

function report(roster) {
  const lines = [];
  for (const [name, athlete] of Object.entries(roster)) {
    try {
      lines.push(`${name} -> [${zones(athlete).join(', ')}]`);
      // Indent the human-readable breakdown underneath the raw array.
      for (const band of describeZones(athlete)) {
        lines.push(`    ${band}`);
      }
    } catch (err) {
      // Bad roster entries are reported rather than aborting the whole run.
      lines.push(`${name} -> error: ${err.message}`);
    }
  }
  return lines.join('\n');
}

const roster = {
  Ana: [22, 65],
  Boris: [40, 50],
  Chen: [55, 72],
  Dana: [30, 190], // resting rate exceeds the estimated maximum
};

console.log(report(roster));

module.exports = { zones, describeZones, report };

