const COLOR_CHANGE_MINUTES = 15;
const MINUTES_PER_HOUR = 60;
const INCHES_PER_YARD = 36;

// The loom descriptor is positional, so name the slots once and reuse the names
function parseLoom(loom) {
  if (!Array.isArray(loom) || loom.length !== 5) {
    throw new TypeError('loom must be an array of five numbers');
  }
  const [picksPerInch, speed, runTimeHours, efficiencyPercent, colorChanges] = loom;
  // A zero pick density would make the fabric length calculation meaningless
  if (!(picksPerInch > 0)) {
    throw new RangeError('picks per inch must be greater than zero');
  }
  return { picksPerInch, speed, runTimeHours, efficiencyPercent, colorChanges };
}

// Efficiency arrives as a percentage but every formula below wants a plain factor
function efficiencyFactor(efficiencyPercent) {
  return efficiencyPercent / 100;
}

// Each color change costs a fixed setup delay, expressed here in hours
function colorChangeDowntime(colorChanges) {
  return (colorChanges * COLOR_CHANGE_MINUTES) / MINUTES_PER_HOUR;
}

function production(loom) {
  const { picksPerInch, speed, runTimeHours, efficiencyPercent, colorChanges } = parseLoom(loom);

  const theoreticalPicksPerHour = speed * MINUTES_PER_HOUR;
  const theoreticalPicks = theoreticalPicksPerHour * runTimeHours;

  // Minor mechanical stops and thread breakages shrink both the picks and the usable hours
  const effectivePicks = theoreticalPicks * efficiencyFactor(efficiencyPercent);
  const effectiveRunTime = effectivePicks / theoreticalPicksPerHour;

  const activeWeavingHours = effectiveRunTime - colorChangeDowntime(colorChanges);
  // A loom that spends all its shift on color changes produces nothing at all
  if (activeWeavingHours <= 0) {
    return 0;
  }

  const actualPicks = activeWeavingHours * theoreticalPicksPerHour;
  const totalInches = actualPicks / picksPerInch;
  const totalYards = totalInches / INCHES_PER_YARD;

  return Math.floor(totalYards);
}

// Small reporting helper so a shift summary can be printed for several looms
function shiftReport(name, loom) {
  const yards = production(loom);
  const { runTimeHours, colorChanges } = parseLoom(loom);
  const lostHours = colorChangeDowntime(colorChanges);
  return `${name}: ${yards} yd over ${runTimeHours} h (${lostHours.toFixed(2)} h lost to setup)`;
}

function main() {
  const looms = [
    ['Loom A', [30, 400, 8, 85, 4]],
    ['Loom B', [48, 520, 12, 92, 2]],
    // A short shift dominated by color changes, to check the degenerate case
    ['Loom C', [24, 300, 1, 60, 6]],
  ];

  for (const [name, loom] of looms) {
    console.log(shiftReport(name, loom));
  }

  // Aggregate the day's output so the mill floor gets a single headline number
  const totalYards = looms.reduce((sum, [, loom]) => sum + production(loom), 0);
  console.log(`Total for the day: ${totalYards} yd`);
}

main();

module.exports = { production, shiftReport };

