const GRAVITY = 9.8;
const SPRING_SPACING_M = 0.15;
const SAFETY_MARGIN = 0.15;

// A trampoline spec is a flat triple, so destructuring is validated before use
function parseSpec(trampoline) {
  if (!Array.isArray(trampoline) || trampoline.length !== 3) {
    throw new TypeError('tension expects [weightKg, heightM, radiusM]');
  }
  const [weightKg, heightM, radiusM] = trampoline.map(Number);
  // Zero or negative dimensions would yield a nonsensical spring count
  if (![weightKg, heightM, radiusM].every((v) => Number.isFinite(v) && v > 0)) {
    throw new RangeError('weight, height and radius must be positive numbers');
  }
  return { weightKg, heightM, radiusM };
}

// Potential energy stored in the jumper at the apex of the bounce
function peakEnergy(weightKg, heightM) {
  return weightKg * heightM * GRAVITY;
}

function landingForce(weightKg, heightM) {
  // Landing doubles the static weight, and higher bounces add further dynamic load
  const loadFactor = 2 + heightM;
  return weightKg * loadFactor * GRAVITY;
}

function matPerimeter(radiusM) {
  return 2 * Math.PI * radiusM;
}

// One spring per 15 cm of mat edge, rounded up so the last gap is never too wide
function springCount(radiusM) {
  return Math.ceil(matPerimeter(radiusM) / SPRING_SPACING_M);
}

function tension(trampoline) {
  const { weightKg, heightM, radiusM } = parseSpec(trampoline);
  const springs = springCount(radiusM);
  const force = landingForce(weightKg, heightM);
  // The landing force is shared equally by every spring around the frame
  const perSpring = force / springs;
  // Extra 15% keeps the steel below its fatigue limit over thousands of cycles
  const rated = perSpring * (1 + SAFETY_MARGIN);
  return [springs, Math.round(rated * 100) / 100];
}

function report(trampoline) {
  const { weightKg, heightM, radiusM } = parseSpec(trampoline);
  const [springs, perSpring] = tension(trampoline);
  const energy = peakEnergy(weightKg, heightM);
  return [
    `Jumper: ${weightKg} kg, bounce ${heightM} m, mat radius ${radiusM} m`,
    // Perimeter is the figure the spring spacing is actually derived from
    `Mat perimeter: ${matPerimeter(radiusM).toFixed(2)} m`,
    `Peak potential energy: ${energy.toFixed(1)} J`,
    `Landing force: ${landingForce(weightKg, heightM).toFixed(1)} N`,
    `Springs: ${springs} @ ${perSpring.toFixed(2)} N each`,
  ].join('\n');
}

function main() {
  const rigs = [
    [70, 1.2, 1.5],
    [45, 0.8, 1.0],
    [95, 2, 2.1],
  ];
  // Each rig is printed as its own block so the numbers stay readable
  for (const rig of rigs) {
    console.log(report(rig));
    console.log('');
  }
}

main();

module.exports = { tension, report, springCount, landingForce, peakEnergy };

