// Kiln firing schedule calculator for a ceramic glaze cycle.

const MINUTES_PER_HOUR = 60;

// A cycle longer than a full day must be supervised overnight.
const OVERNIGHT_LIMIT_HOURS = 24;

// Dense firebrick releases heat slowly, so cooling takes twice the ramp time.
const COOLING_FACTOR = 2;

function validateGlaze(glaze) {
  if (!Array.isArray(glaze) || glaze.length !== 4) {
    throw new TypeError('glaze must be an array of [coneTemp, rampRate, holdMinutes, roomTemp]');
  }
  const [coneTemp, rampRate, holdMinutes, roomTemp] = glaze.map(Number);
  // Any non-numeric entry would silently poison every later division.
  if ([coneTemp, rampRate, holdMinutes, roomTemp].some(Number.isNaN)) {
    throw new TypeError('all glaze parameters must be numeric');
  }
  if (rampRate <= 0) {
    throw new RangeError('ramp rate must be greater than zero degrees per hour');
  }
  // Firing downhill is not a firing at all.
  if (coneTemp <= roomTemp) {
    throw new RangeError('cone temperature must be above room temperature');
  }
  if (holdMinutes < 0) {
    throw new RangeError('hold time cannot be negative');
  }
  return { coneTemp, rampRate, holdMinutes, roomTemp };
}

function fire(glaze) {
  const { coneTemp, rampRate, holdMinutes, roomTemp } = validateGlaze(glaze);

  // Total climb the elements have to deliver.
  const temperatureIncrease = coneTemp - roomTemp;
  const heatingHours = temperatureIncrease / rampRate;

  // The hold (soak) is quoted in minutes but the schedule is kept in hours.
  const holdHours = holdMinutes / MINUTES_PER_HOUR;
  const activeFiringTime = heatingHours + holdHours;

  const coolingHours = heatingHours * COOLING_FACTOR;
  const totalCycleDuration = activeFiringTime + coolingHours;

  // Strictly exceeding 24 h flags the run for overnight monitoring.
  const overnightWarning = totalCycleDuration > OVERNIGHT_LIMIT_HOURS;

  return [activeFiringTime, totalCycleDuration, overnightWarning];
}

function formatSchedule(name, glaze) {
  const [active, total, warning] = fire(glaze);
  const lines = [
    `${name}: active firing ${active.toFixed(2)} h, full cycle ${total.toFixed(2)} h`,
  ];
  // Only mention supervision when the kiln will still be hot in the morning.
  if (warning) {
    lines.push('  WARNING: cycle exceeds 24 h - arrange overnight monitoring');
  }
  return lines.join('\n');
}

function main() {
  const schedules = [
    ['Cone 6 stoneware', [1222, 100, 15, 20]],
    ['Cone 04 bisque', [1060, 150, 30, 22]],
    ['Cone 10 reduction', [1305, 60, 45, 18]],
  ];
  // Report every planned load so the studio can pick a start time.
  for (const [name, glaze] of schedules) {
    console.log(formatSchedule(name, glaze));
  }
}

main();

module.exports = { fire, formatSchedule };

