//: water volume in millilitres dispensed per plant category
const DOSE_ML = { succulent: 50, tropical: 200, standard: 100 };

//: plant types other than these two follow the "standard" rules
function categoryOf(type) {
  const key = String(type).trim().toLowerCase();
  return key in DOSE_ML ? key : 'standard';
}

function needsWater(category, moisture, days) {
  //: succulents tolerate drought, so both conditions must hold
  if (category === 'succulent') {
    return moisture < 10 && days > 14;
  }
  //: tropicals are thirsty: either a dry pot or a long gap triggers watering
  if (category === 'tropical') {
    return moisture < 40 || days > 5;
  }
  return moisture < 25 && days > 7;
}

//: reject malformed rows early so the totals can never be NaN
function parsePlant(entry) {
  if (!Array.isArray(entry) || entry.length < 3) {
    throw new TypeError('each plant must be [type, moisture, days]');
  }
  const [type, moisture, days] = entry;
  if (typeof moisture !== 'number' || Number.isNaN(moisture)) {
    throw new TypeError(`moisture for ${type} must be a number`);
  }
  if (typeof days !== 'number' || Number.isNaN(days)) {
    throw new TypeError(`days since watering for ${type} must be a number`);
  }
  return { category: categoryOf(type), label: String(type), moisture, days };
}

function schedule(plants) {
  let totalMl = 0;
  let count = 0;
  for (const entry of plants) {
    const plant = parsePlant(entry);
    if (needsWater(plant.category, plant.moisture, plant.days)) {
      //: every watered plant receives exactly one dose for its category
      totalMl += DOSE_ML[plant.category];
      count += 1;
    }
  }
  return [totalMl, count];
}

//: human-readable summary for the gardener, derived from the same rules
function report(plants) {
  const lines = plants.map((entry) => {
    const plant = parsePlant(entry);
    const thirsty = needsWater(plant.category, plant.moisture, plant.days);
    //: skipped plants show a dash instead of a dose
    const dose = thirsty ? `${DOSE_ML[plant.category]} ml` : '-';
    return `${plant.label} (${plant.category}): ${plant.moisture}% / ${plant.days}d -> ${dose}`;
  });
  const [totalMl, count] = schedule(plants);
  lines.push(`TOTAL: ${totalMl} ml for ${count} plant(s)`);
  return lines.join('\n');
}

const today = [
  ['Aloe', 5, 20],
  ['Monstera', 50, 2],
  ['Fern', 38, 9],
  ['Basil', 18, 10],
  ['Jade', 30, 21],
];

console.log(report(today));
//: the task's example is the first two rows of the list above
console.log(schedule(today.slice(0, 2)));

module.exports = { schedule, report, needsWater, categoryOf };

