'use strict';

const GRAVITY = 9.8;          // m/s^2
const DRAG_COEFFICIENT = 1.5; // flat-ish round canopy
const SAFE_LANDING_SPEED = 6; // m/s, above this the payload is damaged

// Air gets thinner with height, so the canopy bites less on a high drop.
function airDensity(altitude) {
  if (altitude > 2000) {
    return 1.0;
  }
  // The 1000-2000 m band is the transition layer between thin and sea-level air.
  if (altitude >= 1000) {
    return 1.1;
  }
  return 1.225;
}

// Circular canopy projected onto the airflow: pi * d^2 / 4.
function referenceArea(diameter) {
  return (Math.PI * diameter * diameter) / 4;
}

// Terminal velocity is reached when drag exactly cancels the payload weight.
function terminalVelocity(mass, diameter, altitude) {
  const weight = mass * GRAVITY;
  const drag = airDensity(altitude) * DRAG_COEFFICIENT * referenceArea(diameter);
  return Math.sqrt((2 * weight) / drag);
}

function validate(drop) {
  if (!Array.isArray(drop) || drop.length !== 3) {
    throw new TypeError('drop must be [mass, diameter, altitude]');
  }
  const [mass, diameter, altitude] = drop;
  // A zero mass or zero canopy would make the drag formula meaningless.
  if (!(mass > 0) || !(diameter > 0)) {
    throw new RangeError('mass and diameter must be positive');
