// Film development calculator: base time by film speed, corrected for
// developer temperature and push processing, plus fixing and washing.

const BASE_TIMES = { 100: 6, 400: 8, 3200: 11 };

const STANDARD_TEMP = 20;
const TEMP_COEFFICIENT = 0.05; // 5% per degree of deviation
const PUSH_COEFFICIENT = 0.25; // 25% per stop of push
const FINISHING_TIME = 2; // one minute fixing + one minute washing

function baseTime(speed) {
  // only the three calibrated ISO ratings have published base times
  if (!Object.prototype.hasOwnProperty.call(BASE_TIMES, speed)) {
    throw new Error(`no base development time for ISO ${speed}`);
  }
  return BASE_TIMES[speed];
}

function temperatureFactor(celsius) {
  const deviation = celsius - STANDARD_TEMP;
  // warmer developer works faster, so the multiplier shrinks above 20 C
  return 1 - deviation * TEMP_COEFFICIENT;
}

function pushFactor(stops) {
  // each stop compounds on the already temperature-corrected time
  return Math.pow(1 + PUSH_COEFFICIENT, stops);
}

function waterBathAction(celsius) {
  if (celsius > STANDARD_TEMP) return 'cooled';
  if (celsius < STANDARD_TEMP) return 'heated';
  return 'steady';
}

function develop(batch) {
  const [speed, celsius, stops] = batch;
  // a batch record must carry all three readings to be usable
  if (batch.length !== 3) {
    throw new Error('batch needs speed, temperature and push stops');
  }
  if (!Number.isInteger(stops) || stops < 0) {
    throw new Error('push stops must be a non-negative integer');
  }

  let minutes = baseTime(speed) * temperatureFactor(celsius) * pushFactor(stops);
  minutes += FINISHING_TIME;

  // floating point drift would leave 11.000000000000002 without rounding
  const rounded = Math.round(minutes * 10) / 10;
  return [rounded, waterBathAction(celsius)];
}

function formatReport(batch) {
  const [speed, celsius, stops] = batch;
  const [minutes, action] = develop(batch);
  // one decimal place is the precision a darkroom timer can actually hold
  const time = minutes.toFixed(1);
  return `ISO ${speed} at ${celsius}C, +${stops} stop(s): ${time} min, bath ${action}`;
}

function main() {
  const batches = [
    [400, 22, 1],
    [100, 20, 0],
    [3200, 18, 2],
    [100, 24, 3],
  ];

  for (const batch of batches) {
    // report each roll individually so one bad record does not stop the run
    try {
      console.log(formatReport(batch));
    } catch (err) {
      console.error(`skipping ${JSON.stringify(batch)}: ${err.message}`);
    }
  }
}

main();

module.exports = { develop, formatReport, waterBathAction };

