// Disc golf throw analyzer: estimates distance and classifies flight path.

const GLIDE_NEUTRAL = 4;
const FEET_PER_GLIDE_POINT = 10;

function validateThrow(entry, index) {
  // Each throw must be a triple of numbers; anything else is unusable input.
  if (!Array.isArray(entry) || entry.length !== 3) {
    throw new TypeError(`throw ${index} must be [speed, glide, turn]`);
  }
  const [speed, glide, turn] = entry;
  if (![speed, glide, turn].every((n) => typeof n === 'number' && Number.isFinite(n))) {
    throw new TypeError(`throw ${index} contains a non-numeric rating`);
  }
  // Glide is rated one to seven and turn ranges from negative five to one.
  if (glide < 1 || glide > 7) {
    throw new RangeError(`throw ${index} glide ${glide} is outside 1..7`);
  }
  if (turn < -5 || turn > 1) {
    throw new RangeError(`throw ${index} turn ${turn} is outside -5..1`);
  }
  return { speed, glide, turn };
}

function estimateDistance(speed, glide) {
  // Base distance is five feet of carry per mile per hour of release speed.
  const base = speed * 5;
  return base + (glide - GLIDE_NEUTRAL) * FEET_PER_GLIDE_POINT;
}

function classifyFlight(turn) {
  // Heavily negative turn numbers mean an understable disc that veers right.
  if (turn <= -3) {
    return 'veer right';
  }
  // Turn of zero or one marks an overstable disc that hooks left.
  if (turn >= 0) {
    return 'hook left';
  }
  return 'straight';
}

function analyze(throws) {
  if (!Array.isArray(throws)) {
    throw new TypeError('throws must be an array');
  }
  let maxDistance = -Infinity;
  let straightCount = 0;
  throws.forEach((entry, index) => {
    const { speed, glide, turn } = validateThrow(entry, index);
    const distance = estimateDistance(speed, glide);
    if (distance > maxDistance) {
      maxDistance = distance;
    }
    if (classifyFlight(turn) === 'straight') {
      straightCount += 1;
    }
  });
  // With no throws at all there is no maximum to report, so fall back to zero.
  return [throws.length === 0 ? 0 : maxDistance, straightCount];
}

function report(throws) {
  const lines = throws.map(([speed, glide, turn], index) => {
    const distance = estimateDistance(speed, glide);
    return `#${index + 1}: ${distance} ft, ${classifyFlight(turn)}`;
  });
  const [best, straight] = analyze(throws);
  lines.push(`best: ${best} ft, straight flights: ${straight}`);
  return lines.join('\n');
}

const session = [
  [60, 5, -1],
  [52, 7, -4],
  [48, 3, 0],
  [65, 4, -2],
];

// Driver: print the per-throw breakdown followed by the analyze() summary.
console.log(report(session));
console.log(analyze([[60, 5, -1]]));

module.exports = { analyze, estimateDistance, classifyFlight, report };

