// Substrate estimator for terrarium enclosures.
// Each enclosure is [lengthCm, widthCm, depthCm, animalType].

const BAG_LITERS = 10;

// Multipliers per animal type: amphibians burrow in damp substrate,
// insects trade substrate for air space, reptiles are the baseline.
const ADJUSTMENTS = {
  reptile: 1,
  amphibian: 1.2,
  insect: 0.9
};

function validateEnclosure(enclosure, index) {
  if (!Array.isArray(enclosure) || enclosure.length < 4) {
    throw new TypeError(`enclosure ${index} must be [length, width, depth, animal]`);
  }
  const [length, width, depth, animal] = enclosure;
  // Dimensions arrive as centimeters and must be usable numbers.
  for (const value of [length, width, depth]) {
    if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
      throw new RangeError(`enclosure ${index} has an invalid dimension: ${value}`);
    }
  }
  const key = String(animal).toLowerCase();
  if (!Object.prototype.hasOwnProperty.call(ADJUSTMENTS, key)) {
    throw new RangeError(`enclosure ${index} has an unknown animal type: ${animal}`);
  }
  return { length, width, depth, animal: key };
}

function litersFor(enclosure, index) {
  const { length, width, depth, animal } = validateEnclosure(enclosure, index);
  // Cubic centimeters of substrate, then 1000 cm^3 per liter.
  const cubicCm = length * width * depth;
  return (cubicCm / 1000) * ADJUSTMENTS[animal];
}

function estimate(enclosures) {
  if (!Array.isArray(enclosures)) {
    throw new TypeError('estimate expects an array of enclosures');
  }
  const totalLiters = enclosures.reduce((sum, enclosure, index) => sum + litersFor(enclosure, index), 0);
  // Partial bags are not sold, so always round up to a whole bag.
  const bags = Math.ceil(totalLiters / BAG_LITERS);
  return [totalLiters, bags];
}

function report(enclosures) {
  const lines = enclosures.map((enclosure, index) => {
    const liters = litersFor(enclosure, index);
    const [length, width, depth, animal] = enclosure;
    return `${length}x${width}x${depth} (${animal}): ${liters.toFixed(2)} L`;
  });
  const [totalLiters, bags] = estimate(enclosures);
  // The summary line closes the per-enclosure listing.
  lines.push(`total: ${totalLiters.toFixed(2)} L -> ${bags} bag(s)`);
  return lines.join('\n');
}

function main() {
  const enclosures = [
    [50, 40, 5, 'reptile'],
    [60, 30, 8, 'amphibian'],
    [30, 30, 4, 'insect']
  ];
  console.log(report(enclosures));
  // A single reptile tank of 50x40x5 is the worked example: 10 L, 1 bag.
  console.log(estimate([[50, 40, 5, 'reptile']]));
}

main();

module.exports = { estimate, litersFor, report };

