const GRAVITY = 9.80665;
const BURN_TIME = 1.5;

// Mass arrives in grams because model rocket kits are labelled that way.
function toKilograms(grams) {
  return grams / 1000;
}

function frontalArea(diameterMm) {
  // The body tube diameter is quoted in millimetres; the radius drives the area.
  const radius = diameterMm / 2000;
  return Math.PI * radius * radius;
}

function averageThrust(impulse) {
  // Total impulse spread evenly over the assumed burn gives the mean thrust.
  return impulse / BURN_TIME;
}

function flightProfile(rocket) {
  const [impulse, massGrams, diameterMm] = rocket;
  const mass = toKilograms(massGrams);
  const thrust = averageThrust(impulse);

  // Net acceleration during boost: motor thrust minus weight, drag neglected.
  const acceleration = thrust / mass - GRAVITY;
  const burnoutVelocity = acceleration * BURN_TIME;
  const boostHeight = 0.5 * acceleration * BURN_TIME * BURN_TIME;

  // Unpowered coast trades all kinetic energy for altitude.
  const coastHeight = (burnoutVelocity * burnoutVelocity) / (2 * GRAVITY);

  return {
    thrust,
    area: frontalArea(diameterMm),
    velocity: burnoutVelocity,
    apogee: boostHeight + coastHeight,
  };
}

function estimate(rockets) {
  let best = 0;

  for (const rocket of rockets) {
    if (!Array.isArray(rocket) || rocket.length !== 3) {
      throw new TypeError('each rocket needs impulse, mass and diameter');
    }

    const profile = flightProfile(rocket);

    // Only the record-setting flight matters for the returned figure.
    if (profile.apogee > best) {
      best = profile.apogee;
    }
  }

  return Math.round(best);
}

function report(rockets) {
  return rockets.map((rocket) => {
    const profile = flightProfile(rocket);
    // Areas are tiny, so express them in square centimetres for readability.
    const areaCm2 = (profile.area * 10000).toFixed(2);
    return `${profile.thrust.toFixed(1)} N thrust, ${areaCm2} cm^2 frontal, `
      + `${profile.velocity.toFixed(1)} m/s burnout, ${Math.round(profile.apogee)} m apogee`;
  });
}

const fleet = [
  [10, 50, 24],
  [5, 80, 18],
  [40, 340, 41],
];

// Driver: list every flight, then announce the best altitude of the day.
report(fleet).forEach((line) => console.log(line));
console.log(`Maximum apogee: ${estimate(fleet)} m`);

