const NUTRIENT_STRENGTH = 50; // microsiemens gained per mL of nutrient per liter of water

// Reject malformed tank entries early: bad numbers would silently poison the totals
function validateReservoir(tank, index) {
  if (!Array.isArray(tank) || tank.length < 3) {
    throw new TypeError(`Reservoir ${index} must be [volume, current, target]`);
  }
  const [volume, current, target] = tank;
  if (![volume, current, target].every((n) => typeof n === 'number' && Number.isFinite(n))) {
    throw new TypeError(`Reservoir ${index} contains a non-numeric reading`);
  }
  if (volume <= 0) {
    throw new RangeError(`Reservoir ${index} has a non-positive volume`);
  }
  // Dividing by the target is part of the dilution formula, so zero is not usable
  if (target <= 0) {
    throw new RangeError(`Reservoir ${index} has a non-positive target conductivity`);
  }
  return { volume, current, target };
}

// Too strong: dilute with fresh water proportional to how far past the target we are
function freshWaterFor(volume, deficit, target) {
  return (volume * Math.abs(deficit)) / target;
}

// Too weak: every 50 uS of deficit costs 1 mL of nutrient per liter in the tank
function nutrientFor(volume, deficit) {
  return (deficit / NUTRIENT_STRENGTH) * volume;
}

function roundTenth(value) {
  return Math.round(value * 10) / 10;
}

function dose(reservoirs) {
  if (!Array.isArray(reservoirs)) {
    throw new TypeError('dose expects an array of reservoirs');
  }
  let totalNutrients = 0;
  let totalWater = 0;
  reservoirs.forEach((tank, index) => {
    const { volume, current, target } = validateReservoir(tank, index);
    const deficit = target - current;
    if (deficit < 0) {
      totalWater += freshWaterFor(volume, deficit, target);
    } else if (deficit > 0) {
      totalNutrients += nutrientFor(volume, deficit);
    }
    // A deficit of exactly zero means the tank is already on target
  });
  return [roundTenth(totalNutrients), roundTenth(totalWater)];
}

// Turn the two totals into a line an operator can act on at the mixing station
function formatReport(totals) {
  const [nutrients, water] = totals;
  const actions = [];
  if (nutrients > 0) {
    actions.push(`add ${nutrients.toFixed(1)} mL nutrient`);
  }
  if (water > 0) {
    actions.push(`add ${water.toFixed(1)} L fresh water`);
  }
  return actions.length ? actions.join(' and ') : 'all reservoirs on target';
}

function main() {
  const reservoirs = [
    [10, 1000, 1200], // 200 uS short of target -> 40 mL
    [25, 1800, 1500], // over-concentrated -> dilution
    [8, 900, 900],
  ];
  const totals = dose(reservoirs);
  console.log(totals);
  console.log(formatReport(totals));
}

main();

