// Birdhouse occupancy predictor: maps hole diameter to the species the house targets,
// then scores each house on height and habitat suitability.

const SPECIES_BY_DIAMETER = {
  25: 'chickadee',
  38: 'bluebird',
  50: 'wood duck',
};

// Preferred mounting heights in metres; wood ducks want anything strictly above 3m.
const HEIGHT_PREFERENCE = {
  chickadee: { min: 1, max: 2 },
  bluebird: { min: 1.5, max: 3 },
  'wood duck': { min: 3, max: Infinity, exclusiveMin: true },
};

// Each species gets a bonus only in the habitat it naturally nests in.
const HABITAT_BONUS = {
  bluebird: { field: 30 },
  'wood duck': { wetland: 40 },
  chickadee: { forest: 20 },
};

function speciesFor(diameter) {
  return SPECIES_BY_DIAMETER[diameter] || null;
}

function heightAdjustment(species, height) {
  const range = HEIGHT_PREFERENCE[species];
  const aboveFloor = range.exclusiveMin ? height > range.min : height >= range.min;
  // Inside the preferred band the house is far more attractive; outside it is a mild penalty.
  return aboveFloor && height <= range.max ? 20 : -10;
}

function habitatAdjustment(species, habitat) {
  const bonuses = HABITAT_BONUS[species] || {};
  // Habitat names are compared case-insensitively so "Field" and "field" behave alike.
  return bonuses[String(habitat).trim().toLowerCase()] || 0;
}

function scoreHouse([diameter, height, habitat]) {
  const species = speciesFor(diameter);
  if (!species) {
    // A diameter that matches no target species cannot be scored meaningfully.
    throw new Error(`Unsupported hole diameter: ${diameter}mm`);
  }
  let probability = 50;
  probability += heightAdjustment(species, height);
  probability += habitatAdjustment(species, habitat);
  // Nothing is a certainty in the field, so occupancy is capped at 95%.
  return Math.min(probability, 95);
}

function predict(houses) {
  if (!Array.isArray(houses) || houses.length === 0) {
    // With no houses there is nothing to count and no average to divide by.
    return { highPotentialCount: 0, averageProbability: 0 };
  }
  const probabilities = houses.map(scoreHouse);
  const highPotentialCount = probabilities.filter((p) => p > 70).length;
  const total = probabilities.reduce((sum, p) => sum + p, 0);
  return {
    highPotentialCount,
    averageProbability: total / probabilities.length,
  };
}

function report(houses) {
  const { highPotentialCount, averageProbability } = predict(houses);
  const lines = houses.map((house) => {
    const [diameter, height, habitat] = house;
    // Show the species alongside its score so a builder can see which house to move.
    return `${diameter}mm (${speciesFor(diameter)}) at ${height}m in ${habitat}: ${scoreHouse(house)}%`;
  });
  lines.push(`${highPotentialCount} of ${houses.length} houses above 70%`);
  lines.push(`average probability ${averageProbability.toFixed(1)}%`);
  return lines.join('\n');
}

const trail = [
  [38, 2, 'field'],
  [25, 1.5, 'forest'],
  [50, 4, 'wetland'],
  [25, 3, 'field'],
];

console.log(report(trail));

module.exports = { predict, report, scoreHouse, speciesFor };

