// Solar filter viewing-time calculator.
// Each observation is [opticalDensity, uvIndex, observerAge].

const BASE_DIVISOR = 10000;

function transmissionOf(opticalDensity) {
  // Optical density is logarithmic: transmission drops by a factor of ten per unit.
  return Math.pow(10, -opticalDensity);
}

function uvFactor(uvIndex) {
  // A very high index burns the retina faster, so the allowance shrinks the most.
  if (uvIndex > 8) return 0.7;
  // Moderate-to-high indices still cost ten percent of the allowance.
  if (uvIndex >= 5) return 0.9;
  return 1;
}

function ageFactor(age) {
  // Children's lenses transmit more UV to the retina than adults'.
  if (age < 12) return 0.5;
  // Older eyes recover from photic stress more slowly.
  if (age > 60) return 0.8;
  return 1;
}

function sessionTime(observation) {
  if (!Array.isArray(observation) || observation.length !== 3) {
    throw new TypeError('each observation needs density, UV index and age');
  }
  const [density, uvIndex, age] = observation;
  // Reject non-numeric or infinite readings before they poison the arithmetic.
  if (![density, uvIndex, age].every(Number.isFinite)) {
    throw new TypeError(`non-numeric reading in [${observation}]`);
  }
  const base = 1 / transmissionOf(density) / BASE_DIVISOR;
  return base * uvFactor(uvIndex) * ageFactor(age);
}

function time(observations) {
  if (!Array.isArray(observations) || observations.length === 0) {
    // With no sessions there is nothing to total and no minimum to report.
    return [0, 0];
  }
  const minutes = observations.map(sessionTime);
  const total = minutes.reduce((sum, m) => sum + m, 0);
  const shortest = Math.min(...minutes);
  // Two decimals is finer than any observer can time a session by hand.
  return [round2(total), round2(shortest)];
}

function round2(value) {
  return Math.round(value * 100) / 100;
}

function formatReport(observations) {
  const [total, shortest] = time(observations);
  const lines = observations.map(([density, uvIndex, age], i) => {
    // Index sessions from one so the report reads like an observing log.
    return `session ${i + 1}: OD ${density}, UV ${uvIndex}, age ${age} -> ${round2(sessionTime([density, uvIndex, age]))} min`;
  });
  lines.push(`total ${total} min, shortest ${shortest} min`);
  return lines.join('\n');
}

const log = [
  [5, 9, 10],
  [5, 6, 35],
  [6, 2, 67],
];

console.log(formatReport(log));
// The scalar pair is what callers of time() consume directly.
console.log(time(log));

