const MM_PER_INCH = 25.4;

// a metric designation looks like 205/55R16: width, aspect ratio, rim diameter
const SPEC_PATTERN = /^(\d+)\/(\d+)R(\d+(?:\.\d+)?)$/;

function parseProfile(spec) {
  const match = SPEC_PATTERN.exec(spec.trim());
  if (!match) {
    // refuse to guess at anything that is not a metric designation
    throw new Error(`unrecognised tire specification: ${spec}`);
  }
  return [Number(match[1]), Number(match[2]), Number(match[3])];
}

function sidewallInches(width, aspect) {
  // the aspect ratio is a percentage of the tread width, expressed in millimetres
  const heightMm = (width * aspect) / 100;
  return heightMm / MM_PER_INCH;
}

function overallDiameter(profile) {
  const [width, aspect, wheel] = profile;
  // a sidewall sits above and below the rim, so it counts twice
  return wheel + 2 * sidewallInches(width, aspect);
}

function circumference(diameter) {
  return diameter * Math.PI;
}

function percentDifference(first, second) {
  return ((second - first) / first) * 100;
}

function tire(dimensions) {
  const [first, second] = dimensions;
  // an aspect ratio of zero describes a tire with no sidewall: invalid profile
  if (first[1] === 0 || second[1] === 0) return [];

  const diameterFirst = overallDiameter(first);
  const diameterSecond = overallDiameter(second);
  const circumferenceDiff = percentDifference(
    circumference(diameterFirst),
    circumference(diameterSecond)
  );

  const result = [diameterFirst, diameterSecond, circumferenceDiff];
  if (percentDifference(diameterFirst, diameterSecond) > 3) {
    // beyond 3% the rolling radius upsets speedometer, odometer and ABS calibration
    result.push("Warning: Overall diameter of the second tire exceeds the first by more than 3%.");
  }
  return result;
}

function report(specA, specB) {
  const result = tire([parseProfile(specA), parseProfile(specB)]);
  // an empty list is tire()'s way of rejecting one of the profiles
  if (result.length === 0) return `${specA} vs ${specB}: invalid profile`;

  const [diameterFirst, diameterSecond, circumferenceDiff, warning] = result;
  const lines = [
    `${specA} -> ${diameterFirst.toFixed(2)} in`,
    `${specB} -> ${diameterSecond.toFixed(2)} in`,
    // a signed value reads better than a bare number when comparing two fitments
    `circumference change: ${circumferenceDiff >= 0 ? "+" : ""}${circumferenceDiff.toFixed(2)}%`,
  ];
  if (warning) lines.push(warning);
  return lines.join("\n");
}

function main() {
  const comparisons = [
    ["205/55R16", "225/45R17"],
    ["195/65R15", "215/65R16"],
    // a zero aspect ratio must be reported as invalid rather than measured
    ["205/0R16", "225/45R17"],
  ];
  for (const [specA, specB] of comparisons) {
    console.log(report(specA, specB));
    console.log("");
  }
}

main();

module.exports = { tire, parseProfile, overallDiameter, circumference, report };

