'use strict';

// Conversion and sizing constants used by the whole module
const WATTS_TO_BTU_PER_HOUR = 3.41;
const SWITCH_POWER_WATTS = 50;
const REDUNDANCY_MARGIN_BTU = 5000;

// Facility overhead multipliers keyed by the cooling efficiency level
const OVERHEAD_FACTORS = { standard: 1.3, high: 1.1 };

function validateDatacenter(datacenter) {
  if (!Array.isArray(datacenter) || datacenter.length !== 4) {
    throw new TypeError('datacenter must be [servers, wattsPerServer, switches, efficiency]');
  }
  const [servers, wattsPerServer, switches, efficiency] = datacenter;
  for (const value of [servers, wattsPerServer, switches]) {
    // a negative or non-numeric entry would silently corrupt the power sum
    if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
      throw new RangeError(`expected a non-negative number, got ${value}`);
    }
  }
  if (typeof efficiency !== 'string') {
    throw new TypeError('the cooling efficiency level must be a string');
  }
  const level = efficiency.trim().toLowerCase(); // accept "Standard", " HIGH ", etc.
  if (!Object.prototype.hasOwnProperty.call(OVERHEAD_FACTORS, level)) {
    throw new RangeError(`unknown cooling efficiency level: "${efficiency}"`);
  }
  return { servers, wattsPerServer, switches, level };
}

function itEquipmentPower(servers, wattsPerServer, switches) {
  // servers draw their average load; every switch is budgeted at a flat 50 W
  return servers * wattsPerServer + switches * SWITCH_POWER_WATTS;
}

function wattsToBtu(watts) {
  return watts * WATTS_TO_BTU_PER_HOUR;
}

function round1(value) {
  // binary floating point leaves trailing noise such as 13742.300000000001
  return Math.round(value * 10) / 10;
}

function cooling(datacenter) {
  const { servers, wattsPerServer, switches, level } = validateDatacenter(datacenter);
  const itLoadBtu = wattsToBtu(itEquipmentPower(servers, wattsPerServer, switches));
  const withOverhead = itLoadBtu * OVERHEAD_FACTORS[level];
  return round1(withOverhead + REDUNDANCY_MARGIN_BTU);
}

function coolingReport(name, datacenter) {
  const { servers, wattsPerServer, switches, level } = validateDatacenter(datacenter);
  const itWatts = itEquipmentPower(servers, wattsPerServer, switches);
  const overheadPercent = Math.round((OVERHEAD_FACTORS[level] - 1) * 100);
  const total = cooling(datacenter);
  return [
    `${name}: ${servers} servers @ ${wattsPerServer} W + ${switches} switches`,
    `  IT load        : ${itWatts} W (${round1(wattsToBtu(itWatts))} BTU/h)`,
    // the overhead is reported separately so the facility share stays visible
    `  ${level} overhead: +${overheadPercent}%`,
    `  Backup margin  : +${REDUNDANCY_MARGIN_BTU} BTU/h`,
    `  Required       : ${total} BTU/h`,
  ].join('\n');
}

function main() {
  const sites = [
    ['Edge rack', [10, 300, 2, 'standard']],
    ['Colo hall', [120, 450, 14, 'high']],
  ];
  for (const [name, datacenter] of sites) {
    console.log(coolingReport(name, datacenter));
  }
  // a bad efficiency level must be reported, not rounded into a plausible number
  try {
    cooling([10, 300, 2, 'economy']);
  } catch (err) {
    console.log(`Rejected: ${err.message}`);
  }
}

main();

module.exports = { cooling, coolingReport, itEquipmentPower, wattsToBtu };

