const FOUR_PI_SQUARED = 4 * Math.PI * Math.PI;

// Adjustments smaller than this are mechanically meaningless on a real clock
const TOLERANCE_METERS = 0.001;

function localGravity(length, measuredPeriod) {
  // g = 4*pi^2*L / T^2, derived from the small-angle pendulum period formula
  return (length * FOUR_PI_SQUARED) / (measuredPeriod * measuredPeriod);
}

function idealLength(targetPeriod, gravity) {
  // Inverse of the period formula: L = g*T^2 / (4*pi^2)
  return (targetPeriod * targetPeriod * gravity) / FOUR_PI_SQUARED;
}

function pendulum(settings) {
  const [length, targetPeriod, measuredPeriod] = settings;

  // A measured period of zero would make the gravity calculation blow up
  if (measuredPeriod === 0) {
    return 'Error: measured time period cannot be zero';
  }

  const gravity = localGravity(length, measuredPeriod);
  const ideal = idealLength(targetPeriod, gravity);
  let adjustment = ideal - length;

  // Anything inside the tolerance band counts as already correct
  if (Math.abs(adjustment) < TOLERANCE_METERS) {
    adjustment = 0;
  }

  return [ideal, adjustment];
}

function describe(settings) {
  const result = pendulum(settings);

  // The error case comes back as a plain string rather than a pair
  if (typeof result === 'string') {
    return result;
  }

  const [ideal, adjustment] = result;
  const idealText = `${ideal.toFixed(4)} m`;

  if (adjustment === 0) {
    return `ideal length ${idealText}: within tolerance, leave the bob alone`;
  }

  // A positive adjustment means the rod must grow, which slows the clock down
  const direction = adjustment > 0 ? 'lengthen' : 'shorten';
  return `ideal length ${idealText}: ${direction} by ${Math.abs(adjustment).toFixed(4)} m`;
}

const clocks = [
  // A seconds pendulum running slightly fast, so it needs lengthening
  ['hall clock', [0.9936, 2.0, 1.9968]],
  // Already on target: the correction should collapse to zero
  ['workshop regulator', [0.2484, 1.0, 1.0]],
  // Broken sensor reading that must be rejected
  ['attic clock', [1.0, 2.0, 0]],
];

for (const [name, settings] of clocks) {
  console.log(`${name}: ${describe(settings)}`);
}

module.exports = { pendulum, localGravity, idealLength, describe };

