// Drone payload estimator: computes how much extra mass a multirotor can lift.

// Thrust-to-weight ratios used as safety limits for the two flight styles.
const AGILE_RATIO = 0.5;
const HOVER_RATIO = 0.7;

// Cameras heavier than this need reinforced mounting hardware.
const HEAVY_CAMERA_GRAMS = 500;
const MOUNT_PENALTY_GRAMS = 50;

function parseDrone(drone) {
  if (!Array.isArray(drone) || drone.length !== 4) {
    throw new TypeError('drone must be [thrust, frame, battery, camera]');
  }
  // Coerce once so string inputs from a form or CSV row behave like numbers.
  const values = drone.map(Number);
  if (values.some((v) => !Number.isFinite(v) || v < 0)) {
    throw new RangeError('drone values must be non-negative finite numbers');
  }
  const [thrust, frame, battery, camera] = values;
  return { thrust, frame, battery, camera };
}

function payload(drone) {
  const { thrust, frame, battery, camera } = parseDrone(drone);

  // Dry weight is everything bolted on before any useful load.
  const dryWeight = frame + battery + camera;

  // Without enough thrust to carry itself the airframe never leaves the ground.
  if (thrust < dryWeight) {
    return [0, 0];
  }

  const agileTakeoff = thrust * AGILE_RATIO;
  const hoverTakeoff = thrust * HOVER_RATIO;

  let agilePayload = agileTakeoff - dryWeight;
  let hoverPayload = hoverTakeoff - dryWeight;

  if (camera > HEAVY_CAMERA_GRAMS) {
    // Heavy optics demand a sturdier gimbal mount, eating into both budgets.
    agilePayload -= MOUNT_PENALTY_GRAMS;
    hoverPayload -= MOUNT_PENALTY_GRAMS;
  }

  return [agilePayload, hoverPayload];
}

function describe(name, drone) {
  const [agile, hover] = payload(drone);
  // A negative margin means the limit is already exceeded by the dry weight.
  const verdict = hover > 0 ? 'flyable' : 'overloaded';
  return `${name}: agile ${agile}g, hover ${hover}g (${verdict})`;
}

function main() {
  const fleet = [
    ['Racer 5"', [2400, 320, 180, 40]],
    ['Cinelifter', [9000, 1500, 1100, 750]],
    ['Underpowered toy', [400, 300, 150, 30]],
  ];

  for (const [name, drone] of fleet) {
    // Report each airframe on its own line for a quick fleet overview.
    console.log(describe(name, drone));
  }
}

module.exports = { payload, describe };

// Only run the fleet report when this file is executed directly.
if (require.main === module) {
  main();
}

