// Drivetrain calculator: works out how long a bicycle chain has to be.

const SHORT_CHAINSTAY = 'Error: chainstay length is unusually short';

// Every chain is built from pairs of plates, so only even lengths can be joined.
function roundUpToEven(inches) {
  return Math.ceil(inches / 2) * 2;
}

function chain(bike) {
  const [chainstay, frontTeeth, rearTeeth] = bike;

  // A frame this compact cannot take a normal drivetrain at all.
  if (chainstay < 10) {
    return SHORT_CHAINSTAY;
  }

  // The chain runs from the chainring to the cog and back again.
  let length = chainstay * 2;

  // Roughly half of each gear is wrapped by the chain.
  const gearWrap = (frontTeeth + rearTeeth) / 2;
  length += gearWrap;

  // A smaller chainring than cog is a negative ratio; allow slack for it.
  if (frontTeeth < rearTeeth) {
    length += 4;
  }

  // The rear derailleur cage always eats a couple of inches.
  length += 2;

  return roundUpToEven(length);
}

// Bike specs may arrive from a form or a file, so check them before computing.
function validateBike(bike) {
  if (!Array.isArray(bike) || bike.length !== 3) {
    return 'expected [chainstay, frontTeeth, rearTeeth]';
  }
  const bad = bike.find((value) => typeof value !== 'number' || !Number.isFinite(value) || value <= 0);
  // find() returns the offending entry, which may legitimately be 0 or negative.
  if (bad !== undefined) {
    return `invalid measurement: ${bad}`;
  }
  return null;
}

function describe(name, bike) {
  const problem = validateBike(bike);
  if (problem) {
    return `${name}: cannot measure (${problem})`;
  }

  const result = chain(bike);

  // chain() signals an impossible frame with a string instead of a number.
  if (typeof result === 'string') {
    return `${name}: ${result}`;
  }

  const [chainstay, frontTeeth, rearTeeth] = bike;
  const gearing = `${frontTeeth}t / ${rearTeeth}t`;
  return `${name}: ${chainstay}" chainstay, ${gearing} -> ${result} links`;
}

function main() {
  const garage = [
    ['Road bike', [16, 53, 28]],
    ['Mountain bike', [17.5, 32, 51]],
    ['Folding oddity', [8, 44, 16]],
    ['Tandem', [18, 48, 34]],
    ['Bad data', [16, 'fifty', 28]],
  ];

  // Print one report line per bike in the garage.
  for (const [name, bike] of garage) {
    console.log(describe(name, bike));
  }
}

main();

