// Asphalt paving estimator: turns driveway dimensions into tonnage and truckloads.

const CUBIC_FEET_PER_YARD = 27;
const TONS_PER_CUBIC_YARD = 2.05;
const TRUCK_CAPACITY_TONS = 15;
const MIN_THICKNESS_INCHES = 2;
const WASTE_FACTOR = 1.1;

function paving(driveway) {
  const [length, width, thicknessInches] = driveway;

  // A missing dimension means there is no surface to pave at all.
  if (length === 0 || width === 0) {
    return [0, 0];
  }

  // Thin lifts crack under vehicle load, so the job is refused outright.
  if (thicknessInches < MIN_THICKNESS_INCHES) {
    return 'Error: asphalt thickness must be at least 2 inches.';
  }

  // Work in a single unit system before computing volume.
  const thicknessFeet = thicknessInches / 12;
  const cubicFeet = length * width * thicknessFeet;

  // Asphalt is ordered by the cubic yard, and extra covers subgrade dips and edges.
  const cubicYards = (cubicFeet / CUBIC_FEET_PER_YARD) * WASTE_FACTOR;
  const totalTons = cubicYards * TONS_PER_CUBIC_YARD;

  let truckloads = Math.ceil(totalTons / TRUCK_CAPACITY_TONS);

  // Even a tiny patch job still requires dispatching one truck.
  if (totalTons < 1) {
    truckloads = 1;
  }

  return [totalTons, truckloads];
}

function describeOrder(driveway) {
  const result = paving(driveway);

  // The estimator hands back a message instead of numbers when it rejects the spec.
  if (typeof result === 'string') {
    return result;
  }

  const [tons, truckloads] = result;

  // Zero tonnage corresponds to the degenerate driveway case.
  if (truckloads === 0) {
    return 'No paving required.';
  }

  const trucks = truckloads === 1 ? 'truckload' : 'truckloads';
  return `${tons.toFixed(2)} tons of asphalt, ${truckloads} ${trucks}`;
}

function main() {
  const jobs = [
    [40, 12, 3],
    [100, 20, 4],
    [8, 6, 2],
    [0, 15, 3],
    [50, 10, 1.5],
  ];

  for (const job of jobs) {
    const [length, width, thickness] = job;
    // Print the spec alongside the estimate so quotes stay traceable.
    console.log(`${length}ft x ${width}ft @ ${thickness}in -> ${describeOrder(job)}`);
  }
}

main();

module.exports = { paving, describeOrder };

