// Bonsai wiring calculator: picks aluminum wire gauge for a branch to be bent.

// Input layout of the `branch` list, kept in one place so the parsing stays readable.
const DIAMETER = 0;
const HARDNESS = 1;
const ANGLE = 2;
const SEASON = 3;

// A single wire heavier than this is too stiff to wrap by hand, so it is doubled up.
const MAX_SINGLE_THICKNESS = 6;

function round1(value) {
  // Keep one decimal place; the +Number cast drops the trailing "0" string form.
  return Number(value.toFixed(1));
}

function hardnessMultiplier(score) {
  // Hard woods (4-5) spring back, soft wood (1) needs less metal; 2-3 are the baseline.
  if (score >= 4) return 1.25;
  if (score === 1) return 0.9;
  return 1;
}

function validateBranch(branch) {
  if (!Array.isArray(branch) || branch.length !== 4) {
    throw new TypeError('branch must be [diameter, hardness, angle, season]');
  }
  const hardness = branch[HARDNESS];
  // The hardness table only defines scores one through five.
  if (!Number.isInteger(hardness) || hardness < 1 || hardness > 5) {
    throw new RangeError(`hardness score out of range: ${hardness}`);
  }
  if (branch[DIAMETER] <= 0) {
    throw new RangeError('branch diameter must be positive');
  }
}

function wire(branch) {
  validateBranch(branch);

  // Rule of thumb: the wire is one third of the branch diameter.
  let thickness = (branch[DIAMETER] / 3) * hardnessMultiplier(branch[HARDNESS]);

  if (branch[ANGLE] > 45) {
    // Sharp bends slip, so add a flat half millimetre of holding power.
    thickness += 0.5;
  }

  if (branch[SEASON] === 0) {
    // Winter wood is brittle: thinner wire forces a gentler bend.
    thickness -= 0.2;
  }

  if (thickness > MAX_SINGLE_THICKNESS) {
    // Two thinner wires side by side replace one unmanageable thick wire.
    return ['double', round1(thickness / 2)];
  }
  return ['single', round1(thickness)];
}

function describe(branch) {
  const [count, mm] = wire(branch);
  const season = branch[SEASON] === 1 ? 'spring' : 'winter';
  // "double" means the stated thickness is used twice around the branch.
  const wires = count === 'double' ? `2 x ${mm}mm` : `${mm}mm`;
  return `${branch[DIAMETER]}mm branch, hardness ${branch[HARDNESS]}, ` +
    `${branch[ANGLE]}deg, ${season}: ${wires}`;
}

const workbench = [
  [12, 3, 30, 1],
  [12, 5, 60, 0],
  [60, 4, 50, 1],
  [9, 1, 20, 0],
];

// Print one wiring instruction per branch waiting on the bench.
for (const branch of workbench) {
  console.log(describe(branch));
}

module.exports = { wire, describe };

