//
// DJ transition energy calculator.
//
// A transition is described by four numbers:
//   [outgoingTempo, incomingTempo, keyScore, incomingBaseEnergy]
//

// Key compatibility scores run from 1 (perfect match) to 4 (dissonant);
// the penalty is simply one energy point per step away from perfect.
const KEY_PENALTY = { 1: 0, 2: 1, 3: 2, 4: 3 };

function parseTransition(tracks) {
  if (!Array.isArray(tracks) || tracks.length !== 4) {
    throw new TypeError('transition() expects a list of four numbers');
  }
  const [outgoing, incoming, keyScore, baseEnergy] = tracks.map(Number);
  if ([outgoing, incoming, keyScore, baseEnergy].some(Number.isNaN)) {
    throw new TypeError('all four transition values must be numeric');
  }
  // Only the four documented key scores have a defined penalty.
  if (!Object.prototype.hasOwnProperty.call(KEY_PENALTY, keyScore)) {
    throw new RangeError(`key compatibility score out of range: ${keyScore}`);
  }
  return { outgoing, incoming, keyScore, baseEnergy };
}

// Positive means the incoming track is faster than the outgoing one.
function tempoDifference(outgoing, incoming) {
  return incoming - outgoing;
}

function transition(tracks) {
  const { outgoing, incoming, keyScore, baseEnergy } = parseTransition(tracks);
  const diff = tempoDifference(outgoing, incoming);

  // Half an energy point is gained (or lost) per BPM of tempo change.
  let energy = baseEnergy + diff * 0.5;
  energy -= KEY_PENALTY[keyScore];

  if (diff > 10) {
    // A jump of more than 10 BPM confuses the dancefloor.
    energy -= 1.5;
  }

  energy = Math.min(10, Math.max(1, energy));
  const smooth = diff < 5 && keyScore <= 2;

  // Round to one decimal place, avoiding the trailing float noise of toFixed.
  return [smooth, Math.round(energy * 10) / 10];
}

function describeTransition(tracks) {
  const [smooth, energy] = transition(tracks);
  const [outgoing, incoming] = tracks;
  const label = smooth ? 'smooth' : 'rough';
  return `${outgoing} -> ${incoming} BPM: ${label}, energy ${energy.toFixed(1)}`;
}

function main() {
  const setlist = [
    [128, 130, 1, 6],
    [124, 140, 3, 8],
    [140, 120, 2, 9],
    [126, 126, 4, 5],
  ];

  // Report every planned mix, then flag the ones that need extra work.
  for (const mix of setlist) {
    console.log(describeTransition(mix));
  }

  const rough = setlist.filter((mix) => !transition(mix)[0]);
  console.log(`${rough.length} of ${setlist.length} transitions need rehearsal`);
}

main();

module.exports = { transition, describeTransition, tempoDifference };

