// Aerial firework lift-charge calculator.
// Input format: [diameter (in), weight (g), powder quality (0.8-1.2), wind (m/s)]

const SAFETY_CAP = 100;

function validateShell(shell) {
  // The four fields are positional, so a wrong length cannot be interpreted at all
  if (!Array.isArray(shell) || shell.length !== 4) {
    throw new TypeError('shell must be an array of [diameter, weight, quality, wind]');
  }
  const [diameter, weight, quality, wind] = shell.map(Number);
  if ([diameter, weight, quality, wind].some(Number.isNaN)) {
    throw new TypeError('shell values must all be numeric');
  }
  // Quality outside the documented band would silently distort the division below
  if (quality < 0.8 || quality > 1.2) {
    throw new RangeError('powder quality factor must be between 0.8 and 1.2');
  }
  return { diameter, weight, quality, wind };
}

function charge(shell) {
  const { diameter, weight, quality, wind } = validateShell(shell);

  // Base rule of thumb: one twelfth of the shell mass
  let powder = weight / 12;

  // Better powder burns hotter, so less of it is required
  powder /= quality;

  if (diameter > 4) {
    // Bulky shells need extra impulse to clear the mortar
    powder *= 1.1;
  } else if (diameter === 2) {
    // Two-inch shells launch easily and are over-charged by the base formula
    powder -= 5;
  }

  if (weight < 50) {
    powder -= 2; // lightweight deduction
  }

  // Wind steals altitude, so push the break point higher
  if (wind > 5) {
    powder *= 1.05;
  }

  // Never hand out a charge that could burst the mortar
  if (powder > SAFETY_CAP) {
    powder = SAFETY_CAP;
  }

  return Math.round(powder * 100) / 100;
}

function describeShell(shell) {
  const { diameter, weight, wind } = validateShell(shell);
  const grams = charge(shell);
  // Flag the capped charges so the operator knows the formula was overridden
  const note = grams === SAFETY_CAP ? ' (safety cap applied)' : '';
  return `${diameter}" shell, ${weight} g, ${wind} m/s wind -> ${grams.toFixed(2)} g${note}`;
}

function main() {
  const manifest = [
    [2, 120, 1.0, 2],
    [3, 45, 0.9, 1],
    [6, 900, 1.2, 4],
    [8, 2400, 0.8, 7],
  ];

  // One report line per shell in the firing order
  for (const shell of manifest) {
    console.log(describeShell(shell));
  }
}

main();

module.exports = { charge, describeShell, validateShell };

