text_nat:
// Estimator for the sleep time of a modern unresponsive yo-yo.
// A yo-yo is described as [mass (g), bearing rating (1-5), string thickness (mm), rim weight bias (%)].

const FIELD_NAMES = ['mass', 'bearing spin rating', 'string thickness', 'rim weight bias'];

function validate(yoyo) {
  if (!Array.isArray(yoyo) || yoyo.length !== 4) {
    throw new TypeError('a yo-yo must be described by exactly four values');
  }
  yoyo.forEach((value, index) => {
    // Every specification field has to be a usable finite number.
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      throw new TypeError(`${FIELD_NAMES[index]} must be a finite number`);
    }
  });
  const rating = yoyo[1];
  if (rating < 1 || rating > 5) {
    throw new RangeError('bearing spin rating must be between one and five');
  }
}

function sleep(yoyo) {
  validate(yoyo);
  const [mass, bearing, thickness, rimBias] = yoyo;

  // The rim weight bias tells us how much of the mass actually works as a flywheel.
  const inertialMass = mass * (rimBias / 100);
  let seconds = inertialMass * bearing;

  // Thicker string rubs harder, and the penalty grows with the square of the ratio.
  const frictionFactor = thickness / 0.5;
  seconds -= frictionFactor * frictionFactor;

  if (mass < 60) {
    // Light throws simply run out of momentum sooner.
    seconds *= 0.85;
  }
  if (bearing === 5) {
    // Premium ceramic bearings are worth a flat bonus.
    seconds += 20;
  }
  if (rimBias > 70) {
    // Heavily rim-weighted designs are more stable, so they hold the spin better.
    seconds *= 1.1;
  }

  if (seconds < 0) return 0;
  return Math.round(seconds * 10) / 10;
}

function describe(name, yoyo) {
  const seconds = sleep(yoyo);
  // Zero means the design cannot hold a sleeper at all.
  const verdict = seconds === 0 ? 'does not sleep' : `sleeps ~${seconds.toFixed(1)}s`;
  return `${name.padEnd(14)} ${verdict}`;
}

function main() {
  const lineup = [
    ['Competition', [66, 5, 0.4, 78]],
    ['Mid-range', [64, 3, 0.5, 65]],
    ['Featherweight', [52, 2, 0.6, 60]],
    ['Thick string', [64, 1, 4.0, 50]],
  ];

  // Report each model in the line-up so the estimates can be compared at a glance.
  for (const [name, spec] of lineup) {
    console.log(describe(name, spec));
  }
}

main();

module.exports = { sleep, describe };

