const ASSUMED_CURRENT = 2; // amps drawn by a car under load
const JOINT_RESISTANCE = 0.05; // ohms contributed by each rail joint
const BOOSTER_THRESHOLD = 10; // volts below which a booster is fitted
const LONG_TRACK = 20; // metres above which inductive losses matter

// A layout is described as [supplyVolts, lengthMetres, ohmsPerMetre, jointCount]
function parseTrack(track) {
  if (!Array.isArray(track) || track.length !== 4) {
    throw new TypeError('track must be [volts, metres, ohmsPerMetre, joints]');
  }
  const [supply, length, ohmsPerMetre, joints] = track.map(Number);
  if ([supply, length, ohmsPerMetre, joints].some((n) => !Number.isFinite(n))) {
    throw new TypeError('every track field must be numeric');
  }
  // Negative geometry or resistance has no physical meaning here
  if (length < 0 || ohmsPerMetre < 0 || joints < 0) {
    throw new RangeError('length, resistance and joint count must be >= 0');
  }
  return { supply, length, ohmsPerMetre, joints };
}

function railResistance(length, ohmsPerMetre) {
  return length * ohmsPerMetre;
}

function jointsResistance(joints) {
  return joints * JOINT_RESISTANCE;
}

function voltage(track) {
  const { supply, length, ohmsPerMetre, joints } = parseTrack(track);
  const total = railResistance(length, ohmsPerMetre) + jointsResistance(joints);
  // Ohm's law: the drop is the whole circuit resistance times the load current
  const drop = total * ASSUMED_CURRENT;
  let final = supply - drop;
  if (final < BOOSTER_THRESHOLD) {
    // The booster itself is lossy, costing a further 10% of what is left
    final *= 0.9;
  }
  if (length > LONG_TRACK) {
    final -= 1; // flat allowance for inductive losses on long runs
  }
  return Math.round(final * 100) / 100;
}

function describe(name, track) {
  const { supply, length } = parseTrack(track);
  const end = voltage(track);
  // Report the loss relative to the supply so weak layouts stand out
  const loss = Math.round((supply - end) * 100) / 100;
  return `${name}: ${length} m -> ${end.toFixed(2)} V at the far end (lost ${loss.toFixed(2)} V)`;
}

function main() {
  const layouts = [
    ['Club sprint', [16, 12, 0.02, 8]],
    ['Long rally', [16, 28, 0.03, 20]],
    ['Starved loop', [12, 24, 0.06, 30]],
  ];
  for (const [name, track] of layouts) {
    console.log(describe(name, track));
  }
  // Flag any layout that cannot keep a usable voltage at the furthest point
  const weak = layouts.filter(([, track]) => voltage(track) < BOOSTER_THRESHOLD);
  if (weak.length > 0) {
    console.log('Needs extra power taps: ' + weak.map(([name]) => name).join(', '));
  }
}

main();

module.exports = { voltage, describe, railResistance, jointsResistance };

