'use strict';

// Casing times are derived from a four-field record, so keep the field order in one place
const FIELDS = ['ounces', 'humidity', 'waterTemp', 'dyed'];

function parseLeather(leather) {
  if (!Array.isArray(leather) || leather.length !== FIELDS.length) {
    throw new TypeError(`leather must be a list of ${FIELDS.length} values: ${FIELDS.join(', ')}`);
  }
  const record = {};
  FIELDS.forEach((name, index) => {
    const value = Number(leather[index]);
    // A non-numeric entry would silently poison every later arithmetic step with NaN
    if (!Number.isFinite(value)) {
      throw new TypeError(`${name} must be a finite number, received ${leather[index]}`);
    }
    record[name] = value;
  });
  return record;
}

function casing(leather) {
  const { ounces, humidity, waterTemp, dyed } = parseLeather(leather);

  // Base soak: half an hour of casing per ounce of hide thickness
  let hours = ounces * 0.5;

  if (humidity < 40) {
    // Dry air pulls moisture back out of the fibres, so the hide needs longer
    hours *= 1.2;
  } else if (humidity > 80) {
    // Humid air keeps the hide damp and shortens the required soak
    hours *= 0.7;
  }

  if (waterTemp > 30) {
    // Warm water is absorbed quickly, trimming a full hour off the soak
    hours -= 1;
  } else if (waterTemp < 10) {
    hours += 1; // cold water is sluggish and needs the extra hour back
  }

  // Anything thicker than ten ounces needs a deep penetration soak
  if (ounces > 10) {
    hours += 1.5;
  }

  if (dyed === 1) {
    // Dye seals the pores, so a dyed hide always takes a flat two hours more
    hours += 2;
  }

  // Reductions can stack below the point of usefulness; one hour is the floor
  if (hours < 1) {
    hours = 1;
  }

  return Math.round(hours * 10) / 10;
}

function describeCasing(label, leather) {
  const hours = casing(leather);
  // Singular "hour" only reads correctly at exactly the enforced minimum
  const unit = hours === 1 ? 'hour' : 'hours';
  return `${label}: case for ${hours.toFixed(1)} ${unit}`;
}

function main() {
  const hides = [
    ['8oz natural belt blank', [8, 55, 20, 0]],
    ['12oz saddle skirting', [12, 35, 5, 0]],
    ['4oz dyed lining', [4, 85, 35, 1]],
    ['2oz thin dyed scrap', [2, 90, 32, 1]],
  ];
  // The driver prints one report line per hide in the batch
  for (const [label, leather] of hides) {
    console.log(describeCasing(label, leather));
  }
}

module.exports = { casing, describeCasing };

// Only run the batch report when this file is executed directly
if (require.main === module) {
  main();
}

