const ML_PER_PERCENT = 0.05;
const HEAVY_COVERAGE = 80;
const HEAVY_PENALTY = 1.2;
const DRYING_LIMIT = 250;
const CURL_REDUCTION = 0.9;
const SETUP_WASTE = 5;
const INK_NAMES = ['cyan', 'magenta', 'yellow', 'black'];

// a page is only usable if it carries exactly one percentage per ink
function validatePage(page, index) {
  if (!Array.isArray(page) || page.length !== INK_NAMES.length) {
    throw new TypeError(`page ${index} must be a list of 4 coverage percentages`);
  }
  page.forEach((coverage, slot) => {
    // percentages outside 0..100 cannot be printed, so reject them instead of guessing
    if (typeof coverage !== 'number' || !Number.isFinite(coverage) || coverage < 0 || coverage > 100) {
      throw new RangeError(`page ${index} has an invalid ${INK_NAMES[slot]} coverage: ${coverage}`);
    }
  });
}

// ink used by a single page, before the job-wide setup waste is added
function pageInk(page) {
  const used = page.map((coverage) => {
    const base = coverage * ML_PER_PERCENT;
    // heavy coverage soaks into the paper, so more ink is needed than the linear estimate
    return coverage > HEAVY_COVERAGE ? base * HEAVY_PENALTY : base;
  });

  const totalCoverage = page.reduce((sum, coverage) => sum + coverage, 0);
  if (totalCoverage > DRYING_LIMIT) {
    // black is laid down last, so it is the layer trimmed to keep the sheet flat
    used[3] *= CURL_REDUCTION;
  }
  return used;
}

function estimate(pages) {
  if (!Array.isArray(pages)) {
    throw new TypeError('pages must be a list of pages');
  }

  // every colour starts with the flat setup waste for the whole job
  const totals = INK_NAMES.map(() => SETUP_WASTE);
  pages.forEach((page, index) => {
    validatePage(page, index);
    pageInk(page).forEach((ml, slot) => {
      totals[slot] += ml;
    });
  });

  // one decimal place is the precision of the shop's measuring cups
  return totals.map((ml) => Math.round(ml * 10) / 10);
}

function report(pages) {
  const totals = estimate(pages);
  const lines = totals.map((ml, slot) => `${INK_NAMES[slot].padEnd(8)} ${ml.toFixed(1)} ml`);
  // the grand total is recomputed from the rounded figures the operator will actually read
  const grand = totals.reduce((sum, ml) => sum + ml, 0);
  lines.push(`${'total'.padEnd(8)} ${grand.toFixed(1)} ml`);
  return lines.join('\n');
}

const job = [
  [10, 20, 30, 40],
  [85, 10, 10, 10],
  [90, 90, 90, 90],
  [0, 0, 0, 0],
];

console.log(`job of ${job.length} pages`);
console.log(report(job));

// a single light page shows the floor of the estimate: the setup waste dominates
console.log(estimate([[1, 1, 1, 1]]));

module.exports = { estimate, pageInk, report };

