const MIN_LAP_TIME = 30;
const BASE_WEIGHT = 70;
const CORNER_PENALTY = 1.5;

// The four metrics always arrive in this fixed order
const FIELDS = ['length', 'corners', 'topSpeed', 'weight'];

function parseMetrics(metrics) {
  if (!Array.isArray(metrics) || metrics.length !== FIELDS.length) {
    throw new TypeError(`expected ${FIELDS.length} metrics: ${FIELDS.join(', ')}`);
  }
  const parsed = {};
  FIELDS.forEach((field, i) => {
    const value = Number(metrics[i]);
    if (!Number.isFinite(value) || value <= 0) {
      // a zero top speed would divide by zero, the rest are physically impossible
      throw new RangeError(`${field} must be a positive number, got ${metrics[i]}`);
    }
    parsed[field] = value;
  });
  return parsed;
}

function weightPenalty(weight) {
  const excess = weight - BASE_WEIGHT;
  // drivers at or under the reference weight carry no penalty at all
  if (excess <= 0) return 0;
  // the penalty is charged per full block of 10 kg above the reference
  return Math.floor(excess / 10) * 0.2;
}

function predict(metrics) {
  const { length, corners, topSpeed, weight } = parseMetrics(metrics);

  // ideal time is the distance covered while holding top speed the whole way
  let time = length / topSpeed;

  // every corner costs braking and acceleration time
  time += corners * CORNER_PENALTY;
  time += weightPenalty(weight);

  if (length > 1000) {
    // long tracks tire the driver, so everything so far gets 5% slower
    time *= 1.05;
  }

  // no lap may beat the absolute track record
  if (time < MIN_LAP_TIME) time = MIN_LAP_TIME;

  return Math.round(time * 10) / 10;
}

function formatPrediction(metrics) {
  const { length, corners } = parseMetrics(metrics);
  const seconds = predict(metrics);
  const minutes = Math.floor(seconds / 60);
  // pad the seconds so 1:05.4 does not come out as 1:5.4
  const rest = (seconds - minutes * 60).toFixed(1).padStart(4, '0');
  return `${length}m / ${corners} corners -> ${minutes}:${rest} (${seconds}s)`;
}

const tracks = [
  [1200, 8, 45, 92],
  [800, 4, 60, 70],
  [400, 2, 50, 68],
];

// report every configuration the strategist asked about
for (const track of tracks) {
  console.log(formatPrediction(track));
}

module.exports = { predict, formatPrediction, weightPenalty, parseMetrics };

