// Estimating how long a wet-extracted carpet needs before it is walkable again.

const BASE_EXTRACTION_RATE = 0.8;
const MAX_EXTRACTION_RATE = 0.95;
const HOURS_PER_LITER = 2;

// A reading is usable only if all four values are finite numbers.
function validateReadings(carpet) {
  if (!Array.isArray(carpet) || carpet.length !== 4) {
    throw new TypeError('carpet must be [water, lift, pileDepth, humidity]');
  }
  const [water, lift, pileDepth, humidity] = carpet.map(Number);
  if ([water, lift, pileDepth, humidity].some((value) => !Number.isFinite(value))) {
    throw new TypeError('carpet readings must all be numeric');
  }
  return { water, lift, pileDepth, humidity };
}

// Suction lift above 100 buys one extra percent of extraction per unit.
function extractionRate(lift) {
  const bonus = Math.max(0, lift - 100) / 100;
  return Math.min(MAX_EXTRACTION_RATE, BASE_EXTRACTION_RATE + bonus);
}

function residualWater(water, lift) {
  // Whatever the wand fails to pull out stays in the pile and has to evaporate.
  return water * (1 - extractionRate(lift));
}

// Deep pile holds water further from the surface: 10% slower per mm past 10.
function pileFactor(pileDepth) {
  return 1 + 0.1 * Math.max(0, pileDepth - 10);
}

function humidityFactor(humidity) {
  // Above 60% RH the air is too saturated to carry moisture away quickly.
  return humidity > 60 ? 1.5 : 1;
}

function extract(carpet) {
  const { water, lift, pileDepth, humidity } = validateReadings(carpet);
  const leftBehind = residualWater(water, lift);
  const hours = leftBehind * HOURS_PER_LITER * pileFactor(pileDepth) * humidityFactor(humidity);
  // The job sheet only ever quotes drying time to a single decimal.
  return Math.round(hours * 10) / 10;
}

// Turn one job's numbers into a line a technician can read off the sheet.
function describeJob(label, carpet) {
  const { water, lift, pileDepth, humidity } = validateReadings(carpet);
  const ratePercent = (extractionRate(lift) * 100).toFixed(0);
  const hours = extract(carpet);
  return `${label}: ${water} L applied, ${ratePercent}% extracted, ` +
    `${pileDepth} mm pile, ${humidity}% RH -> ${hours.toFixed(1)} h`;
}

function main() {
  const jobs = [
    ['Reception runner', [10, 100, 8, 40]],
    ['Conference room', [12, 130, 14, 55]],
    ['Basement office', [8, 110, 12, 75]],
    ['Show suite', [6, 250, 10, 30]],
  ];

  for (const [label, carpet] of jobs) {
    console.log(describeJob(label, carpet));
  }

  // Scheduling needs the worst case, since the crew returns once for the lot.
  const longest = Math.max(...jobs.map(([, carpet]) => extract(carpet)));
  console.log(`Return visit after ${longest.toFixed(1)} hours`);
}

main();

module.exports = { extract, extractionRate, residualWater, describeJob };

