const STRIDES_PER_SECOND = 3;
const OBSTACLE_PENALTY = 1.2;
const TIGHT_COURSE_LIMIT = 4;
const COMPLEXITY_MULTIPLIER = 1.2;
const MINIMUM_TIME = 10;

// A course is described as [obstacles, averageDistance, strideLength]
function parseCourse(course) {
  if (!Array.isArray(course) || course.length !== 3) {
    throw new TypeError('A course must be a list of exactly three numbers');
  }
  const [obstacles, averageDistance, strideLength] = course.map(Number);
  if ([obstacles, averageDistance, strideLength].some(Number.isNaN)) {
    throw new TypeError('Course entries must be numeric');
  }
  // A stride length of zero would make the dog's speed zero and the time infinite
  if (strideLength <= 0) {
    throw new RangeError('Stride length must be greater than zero');
  }
  if (obstacles < 0 || averageDistance < 0) {
    throw new RangeError('Obstacle count and distance cannot be negative');
  }
  return { obstacles, averageDistance, strideLength };
}

// Speed comes from the stride geometry: three strides of the given length each second
function speedOf(strideLength) {
  return strideLength * STRIDES_PER_SECOND;
}

function plan(course) {
  const { obstacles, averageDistance, strideLength } = parseCourse(course);
  const totalDistance = obstacles * averageDistance;
  let time = totalDistance / speedOf(strideLength);
  // Every obstacle costs extra time for the jump and the turn out of it
  time += obstacles * OBSTACLE_PENALTY;
  if (averageDistance < TIGHT_COURSE_LIMIT) {
    // Obstacles packed close together leave no room to accelerate
    time *= COMPLEXITY_MULTIPLIER;
  }
  // Even a trivial course still takes the handler and dog a while to clear
  return Math.round(Math.max(time, MINIMUM_TIME));
}

// Turn a plan into something a handler can read off a clipboard
function describe(name, course) {
  const { obstacles, averageDistance } = parseCourse(course);
  const seconds = plan(course);
  const layout = averageDistance < TIGHT_COURSE_LIMIT ? 'tight' : 'open';
  return `${name}: ${obstacles} obstacles, ${layout} layout, ${seconds}s`;
}

// Sorting by predicted time gives the running order for the day
function runningOrder(entries) {
  return entries
    .map(([name, course]) => ({ name, seconds: plan(course) }))
    .sort((a, b) => a.seconds - b.seconds || a.name.localeCompare(b.name));
}

function main() {
  const entries = [
    ['Rex', [12, 5, 0.9]],
    ['Bella', [12, 3.5, 0.9]],
    ['Pip', [4, 6, 0.55]],
    ['Scout', [1, 8, 1.1]],
  ];
  for (const [name, course] of entries) {
    console.log(describe(name, course));
  }
  console.log('--- running order ---');
  // The fastest predicted run goes first so the ring warms up gradually
  for (const { name, seconds } of runningOrder(entries)) {
    console.log(`${name} -> ${seconds}s`);
  }
}

main();

module.exports = { plan, describe, runningOrder };

