const FREEZING_F = 32;
const RATE_PER_SQUARE_INCH = 0.05;
const TEMP_BOOST_PER_DEGREE = 0.10;
const SUNLIGHT_BONUS = 20;
const STALLED_HOURS = 999;

// A sculpture is the 4-tuple [volume, surfaceArea, temperature, inSunlight].
function validateSculpture(sculpture) {
  if (!Array.isArray(sculpture) || sculpture.length !== 4) {
    throw new TypeError('sculpture must be a list of 4 values');
  }
  const [volume, surfaceArea, temperature, inSunlight] = sculpture;
  for (const value of [volume, surfaceArea, temperature]) {
    // NaN slips past typeof, so it has to be excluded explicitly.
    if (typeof value !== 'number' || Number.isNaN(value)) {
      throw new TypeError('volume, surface area and temperature must be numbers');
    }
  }
  if (volume < 0) {
    throw new RangeError('volume cannot be negative');
  }
  // A block with no exposed surface would give a zero divisor later on.
  if (surfaceArea <= 0) {
    throw new RangeError('surface area must be positive');
  }
  if (typeof inSunlight !== 'boolean') {
    throw new TypeError('sunlight flag must be a boolean');
  }
  return { volume, surfaceArea, temperature, inSunlight };
}

function meltRate(surfaceArea, temperature, inSunlight) {
  const base = surfaceArea * RATE_PER_SQUARE_INCH;
  // Only degrees strictly above freezing accelerate the melt.
  const degreesAboveFreezing = Math.max(0, temperature - FREEZING_F);
  let rate = base * (1 + TEMP_BOOST_PER_DEGREE * degreesAboveFreezing);
  if (inSunlight) {
    // Radiant heat is a flat addition, not a percentage of the surface rate.
    rate += SUNLIGHT_BONUS;
  }
  return rate;
}

function melt(sculpture) {
  const { volume, surfaceArea, temperature, inSunlight } = validateSculpture(sculpture);
  if (temperature <= FREEZING_F && !inSunlight) {
    // Nothing drives the phase change, so the block is effectively permanent.
    return STALLED_HOURS;
  }
  const hours = volume / meltRate(surfaceArea, temperature, inSunlight);
  return Math.round(hours * 10) / 10;
}

function describe(sculpture) {
  const [volume, surfaceArea, temperature, inSunlight] = sculpture;
  const hours = melt(sculpture);
  const sun = inSunlight ? 'full sun' : 'shade';
  const label = `${volume} in³ / ${surfaceArea} in² at ${temperature}°F in ${sun}`;
  // The sentinel is a status flag rather than a measurement, so it reads differently.
  const verdict = hours === STALLED_HOURS ? 'melting stalled' : `${hours.toFixed(1)} h`;
  return `${label}: ${verdict}`;
}

function main() {
  const gallery = [
    [1000, 600, 75, false],
    [1000, 600, 75, true],
    [1000, 600, 32, false],
    [500, 300, 20, true],
    [2400, 800, 33, false],
  ];
  for (const sculpture of gallery) {
    console.log(describe(sculpture));
  }
}

main();

module.exports = { melt, meltRate, describe };

