const FIBER_LOSS_PER_KM = 0.25;
const REFLECTION_PENALTY = 0.1;
const SPLICES_PER_PENALTY = 3;
const AMPLIFICATION_THRESHOLD = 20;

// A route is only meaningful when it at least carries the fiber length
function parseRoute(route) {
  if (!Array.isArray(route) || route.length === 0) {
    throw new TypeError('route must be a non-empty array of numbers');
  }
  const numbers = route.map((value, index) => {
    // reject anything that is not a finite number, including strings and NaN
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      throw new TypeError(`route[${index}] is not a finite number`);
    }
    return value;
  });
  const [length, ...splices] = numbers;
  if (length < 0 || splices.some((loss) => loss < 0)) {
    throw new RangeError('lengths and losses cannot be negative');
  }
  return { length, splices };
}

function round2(value) {
  // shift by two digits so that Math.round works on the cents-like scale
  return Math.round(value * 100) / 100;
}

function estimate(route) {
  const { length, splices } = parseRoute(route);
  const fiberLoss = length * FIBER_LOSS_PER_KM;
  const spliceLoss = splices.reduce((sum, loss) => sum + loss, 0);
  // every complete group of three splices contributes one reflection penalty
  const groups = Math.floor(splices.length / SPLICES_PER_PENALTY);
  const total = round2(fiberLoss + spliceLoss + groups * REFLECTION_PENALTY);
  return [total, total > AMPLIFICATION_THRESHOLD];
}

// Human readable breakdown used by the reporting driver below
function describe(name, route) {
  const [total, needsAmplifier] = estimate(route);
  const spliceCount = route.length - 1;
  const verdict = needsAmplifier ? 'amplifier required' : 'passive link ok';
  return `${name}: ${route[0]} km, ${spliceCount} splices -> ${total.toFixed(2)} dB (${verdict})`;
}

function main() {
  const links = [
    ['metro-ring', [12, 0.3, 0.2, 0.25]],
    ['coastal-haul', [64, 0.5, 0.4, 0.3, 0.2, 0.2, 0.35]],
    ['transcontinental', [95, 0.5, 0.5, 0.5, 0.5]],
  ];
  for (const [name, route] of links) {
    console.log(describe(name, route));
  }
  // a malformed route should surface as a clear diagnostic, not a silent NaN
  try {
    estimate([40, 'splice']);
  } catch (error) {
    console.log(`rejected: ${error.message}`);
  }
}

// run the driver only when this file is executed directly
if (require.main === module) {
  main();
}

module.exports = { estimate, describe };

