  const { temperature, dewPoint } = parseConditions(conditions);
  // pilots fly circuits relative to the field, hence the AGL variant in metres
  return Math.round(convergenceHeightFeet(spread(temperature, dewPoint)) * FEET_TO_METRES);
}

