const IDEAL_RISER = 175;
const MIN_RISER = 170;
const MAX_RISER = 180;

// the architectural rule "2R + T = 630" fixes the tread once the riser is known
const STEP_FORMULA_TOTAL = 630;

function round1(value) {
  return Math.round(value * 10) / 10;
}

function plan(height) {
  if (typeof height !== 'number' || !Number.isFinite(height)) {
    throw new TypeError('height must be a finite number of millimetres');
  }
  // a staircase needs a positive rise, otherwise there is nothing to climb
  if (height <= 0) {
    throw new RangeError('height must be greater than zero');
  }
  const steps = Math.round(height / IDEAL_RISER);
  // a rise below ~88 mm rounds down to zero steps, so keep a single step floor
  const stepCount = steps < 1 ? 1 : steps;
  const riser = height / stepCount;
  const tread = STEP_FORMULA_TOTAL - 2 * riser;
  return [stepCount, round1(riser), round1(tread)];
}

function comfortOf(riser) {
  // risers outside the safety window are legal-ish but uncomfortable to walk
  if (riser < MIN_RISER) return 'shallow';
  if (riser > MAX_RISER) return 'steep';
  return 'ideal';
}

function totalRun(steps, tread) {
  // the last riser lands on the upper floor, so there are steps - 1 treads
  return round1((steps - 1) * tread);
}

function describe(height) {
  const [steps, riser, tread] = plan(height);
  return {
    height,
    steps,
    riser,
    tread,
    comfort: comfortOf(riser),
    run: totalRun(steps, tread),
  };
}

function formatRow(height) {
  const s = describe(height);
  // pad every column so the table stays readable in a plain terminal
  return [
    String(s.height).padEnd(8),
    String(s.steps).padStart(5),
    s.riser.toFixed(1).padStart(7),
    s.tread.toFixed(1).padStart(7),
    s.run.toFixed(1).padStart(7),
    s.comfort.padStart(9),
  ].join(' ');
}

function formatReport(rises) {
  const header = 'rise(mm)  steps  riser  tread  run     comfort';
  return [header, ...rises.map(formatRow)].join('\n');
}

function main() {
  // typical floor to floor rises: flat, house, loft conversion, tall villa
  const rises = [2600, 2800, 3000, 3250, 4000];
  console.log(formatReport(rises));
}

main();

module.exports = { plan, describe, formatReport };

