// Simplified DNA translation: read codons, start at ATG, stop at TAA/TAG/TGA.

// Codons that terminate translation immediately.
const STOP_CODONS = ['TAA', 'TAG', 'TGA'];

// Prefix based mapping for the intermediate codons we recognise.
const PREFIX_TABLE = {
  TT: 'Phenylalanine',
  CT: 'Leucine',
  GT: 'Valine'
};

function normalize(sequence) {
  if (typeof sequence !== 'string') {
    throw new TypeError('translate() expects a nucleotide string');
  }
  // Accept lower case input and drop whitespace or separators pasted in from FASTA files.
  return sequence.toUpperCase().replace(/[^ACGT]/g, '');
}

function toCodons(cleaned) {
  const codons = [];
  for (let i = 0; i + 3 <= cleaned.length; i += 3) {
    codons.push(cleaned.slice(i, i + 3));
  }
  // A trailing fragment of one or two letters never forms a codon, so the loop above leaves it out.
  return codons;
}

function codonToAmino(codon) {
  if (codon === 'ATG') {
    return 'Methionine';
  }
  return PREFIX_TABLE[codon.slice(0, 2)] || null;
}

function translate(sequence) {
  const codons = toCodons(normalize(sequence));
  const aminoAcids = [];
  let started = false;

  for (const codon of codons) {
    if (STOP_CODONS.includes(codon)) {
      // Stop codons end the chain whether or not translation ever began.
      break;
    }
    if (!started) {
      // Everything ahead of the first ATG belongs to the untranslated leader.
      if (codon !== 'ATG') continue;
      started = true;
    }
    const amino = codonToAmino(codon);
    if (amino !== null) {
      aminoAcids.push(amino);
    }
  }

  return aminoAcids.join('-');
}

function report(sequence) {
  const chain = translate(sequence);
  // An empty chain means no ATG was reached before a stop codon or the end of the strand.
  const shown = chain === '' ? '(no protein)' : chain;
  return `${sequence} -> ${shown}`;
}

function main() {
  const strands = [
    'ATGTTTCTGGTATAA',
    'GGCATGCTCTTAGTGTGACCC',
    'ATG',
    'TTTCTTATG',
    'atgGTCttAGG'
  ];
  // Print one translation per strand so the driver exercises the whole pipeline.
  for (const strand of strands) {
    console.log(report(strand));
  }
}

main();

module.exports = { translate, codonToAmino, toCodons, normalize, report };

