// RPG level-up simulator: grows a character's stats from level 1 to a target level.

const ARCHETYPES = ['warrior', 'mage', 'rogue'];

// Per-level gains keyed by archetype; these apply once for every level above the first.
const GAINS = {
  warrior: { health: 10, strength: 3 },
  mage: { health: 4, strength: 1 },
  rogue: { health: 7, strength: 2 }
};

function validate(stats) {
  if (!Array.isArray(stats) || stats.length !== 4) {
    throw new TypeError('stats must be [level, health, strength, archetype]');
  }
  const [targetLevel, health, strength, archetype] = stats;
  // The loop below cannot run at all unless the target level is a whole number of at least one.
  if (!Number.isInteger(targetLevel) || targetLevel < 1) {
    throw new RangeError(`invalid target level: ${targetLevel}`);
  }
  if (typeof health !== 'number' || typeof strength !== 'number') {
    throw new TypeError('base health and strength must be numbers');
  }
  // Archetype decides the whole growth curve, so an unknown one is unrecoverable.
  if (!ARCHETYPES.includes(archetype)) {
    throw new RangeError(`unknown archetype: ${archetype}`);
  }
  return { targetLevel, health, strength, archetype };
}

function level(stats) {
  const { targetLevel, health, strength, archetype } = validate(stats);
  const gain = GAINS[archetype];
  let currentHealth = health;
  let currentStrength = strength;

  // Level one is the starting point, so gains begin at level two.
  for (let lvl = 2; lvl <= targetLevel; lvl += 1) {
    currentHealth += gain.health;
    currentStrength += gain.strength;

    if (archetype === 'mage' && lvl % 5 === 0) {
      // Mage attunement: a ten percent multiplier on everything accumulated so far.
      currentHealth *= 1.1;
      currentStrength *= 1.1;
    } else if (archetype === 'rogue' && lvl % 2 === 0) {
      // Rogue opportunism: a flat five to both stats on even numbered levels only.
      currentHealth += 5;
      currentStrength += 5;
    }
  }

  return [Math.floor(currentHealth), Math.floor(currentStrength)];
}

function describe(stats) {
  const [finalHealth, finalStrength] = level(stats);
  const [targetLevel, , , archetype] = stats;
  const name = archetype[0].toUpperCase() + archetype.slice(1);
  return `${name} at level ${targetLevel}: ${finalHealth} HP / ${finalStrength} STR`;
}

function main() {
  const party = [
    [20, 100, 10, 'warrior'],
    [20, 100, 10, 'mage'],
    [20, 100, 10, 'rogue'],
    [1, 85, 12, 'mage']
  ];

  for (const member of party) {
    console.log(describe(member));
  }

  // Compare the archetypes at the end of a long campaign to see who scales best.
  const campaign = party.slice(0, 3).map((member) => [member[3], level([50, 100, 10, member[3]])]);
  campaign.sort((a, b) => b[1][0] - a[1][0]);
  console.log(`Toughest at level 50: ${campaign[0][0]} with ${campaign[0][1][0]} HP`);
}

main();

module.exports = { level, describe };

