const MINUTES_PER_DEGREE = 60;

// converts decimal degrees into radians for the trigonometric helpers below
function toRadians(degrees) {
  return (degrees * Math.PI) / 180;
}

function round4(value) {
  // rounding is done on a scaled integer to avoid binary artefacts like 12.34449999
  return Math.round(value * 10000) / 10000;
}

// keeps a longitude inside the conventional -180..180 range after crossing the antimeridian
function normalizeLongitude(lon) {
  let wrapped = ((lon + 180) % 360 + 360) % 360;
  return wrapped - 180;
}

function navigate(leg) {
  const [lat, lon, heading, speed, hours] = leg;
  // a leg built from bad sensor data must not silently produce NaN coordinates
  if (![lat, lon, heading, speed, hours].every(Number.isFinite)) {
    throw new TypeError('navigate expects five finite numbers');
  }
  // at the poles the cosine of the latitude vanishes and the east/west term explodes
  if (Math.abs(lat) >= 90) {
    throw new RangeError(`starting latitude ${lat} is not navigable`);
  }
  const headingRad = toRadians(heading);
  const distance = speed * hours;
  // one nautical mile equals one minute of latitude, so sixty minutes make a degree
  const deltaLat = (distance * Math.cos(headingRad)) / MINUTES_PER_DEGREE;
  const newLat = lat + deltaLat;
  // meridians converge with latitude, hence the division by the cosine of the start latitude
  const deltaLon =
    (distance * Math.sin(headingRad)) / MINUTES_PER_DEGREE / Math.cos(toRadians(lat));
  return [round4(newLat), round4(normalizeLongitude(lon + deltaLon))];
}

function sailPassage(start, courses) {
  const fixes = [];
  let [lat, lon] = start;
  for (const [heading, speed, hours] of courses) {
    // each leg starts from the fix produced by the previous one
    [lat, lon] = navigate([lat, lon, heading, speed, hours]);
    fixes.push([lat, lon]);
  }
  return fixes;
}

function formatCoordinate(lat, lon) {
  const parts = [
    { value: lat, positive: 'N', negative: 'S' },
    { value: lon, positive: 'E', negative: 'W' },
  ];
  return parts
    .map(({ value, positive, negative }) => {
      const hemisphere = value < 0 ? negative : positive;
      const magnitude = Math.abs(value);
      const degrees = Math.floor(magnitude);
      // the fractional degree is reported as decimal minutes, as on a paper chart
      const minutes = (magnitude - degrees) * MINUTES_PER_DEGREE;
      return `${degrees}\u00B0${minutes.toFixed(1)}'${hemisphere}`;
    })
    .join(' ');
}

function main() {
  const departure = [34.05, -118.25];
  const courses = [
    [225, 12.5, 6],
    [180, 10, 12],
    [90, 14.2, 30],
  ];
  const fixes = sailPassage(departure, courses);
  console.log(`Departure: ${formatCoordinate(departure[0], departure[1])}`);
  fixes.forEach(([lat, lon], index) => {
    const [heading, speed, hours] = courses[index];
    // the raw pair is echoed next to the chart notation for log-book cross checking
    console.log(
      `Leg ${index + 1}: ${heading}\u00B0 at ${speed}kn for ${hours}h -> ` +
        `${formatCoordinate(lat, lon)}  [${lat}, ${lon}]`
    );
  });
}

main();

