const MAINTENANCE_LONG = 0.25;
const MAINTENANCE_SHORT = 0.30;

// The four fields arrive positionally, so unpack them once and validate before any math
function parseAccount(account) {
  if (!Array.isArray(account) || account.length !== 4) {
    throw new TypeError('account must be a list of [cash, longValue, shortValue, initialMarginRate]');
  }
  const [cash, longValue, shortValue, initialMarginRate] = account.map(Number);
  if ([cash, longValue, shortValue, initialMarginRate].some(Number.isNaN)) {
    throw new TypeError('all account fields must be numeric');
  }
  // market values are absolute magnitudes: a short position is reported as a positive number
  if (longValue < 0 || shortValue < 0) {
    throw new RangeError('position market values cannot be negative');
  }
  // the broker rate is a pure decimal (0.5 means 50%), not a percentage point value
  if (initialMarginRate < 0 || initialMarginRate > 1) {
    throw new RangeError('initialMarginRate must be a decimal between 0 and 1');
  }
  return { cash, longValue, shortValue, initialMarginRate };
}

// Real equity is what the account would be worth after closing everything out
function realEquity({ cash, longValue, shortValue }) {
  return cash + longValue - shortValue;
}

// Maintenance margin is charged separately against each side of the book
function requiredMargin({ longValue, shortValue }) {
  return MAINTENANCE_LONG * longValue + MAINTENANCE_SHORT * shortValue;
}

function assess(account) {
  const parsed = parseAccount(account);
  const equity = realEquity(parsed);
  const required = requiredMargin(parsed);
  // the deficit is severe the moment equity slips under the maintenance floor
  const marginCall = equity < required;
  return [equity, required, marginCall];
}

function money(value) {
  const sign = value < 0 ? '-' : '';
  // fixed two decimals keeps cents visible in the liquidation notice
  return `${sign}$${Math.abs(value).toFixed(2)}`;
}

// Human-readable summary used by the risk desk when reviewing flagged accounts
function report(account) {
  const { longValue, shortValue, initialMarginRate } = parseAccount(account);
  const [equity, required, marginCall] = assess(account);
  const initialRequirement = initialMarginRate * (longValue + shortValue);
  const verdict = marginCall
    ? `MARGIN CALL: short ${money(required - equity)}`
    : `OK: cushion ${money(equity - required)}`;
  return [
    `equity ${money(equity)}`,
    `maintenance ${money(required)}`,
    `initial @ ${(initialMarginRate * 100).toFixed(1)}% ${money(initialRequirement)}`,
    verdict,
  ].join(' | ');
}

function main() {
  const book = [
    [10000, 20000, 0, 0.5],
    [2000, 30000, 0, 0.5],
    [5000, 0, 20000, 0.5],
    [-15000, 25000, 5000, 0.6],
  ];
  // one line per account so the desk can scan the whole book at a glance
  for (const account of book) {
    console.log(report(account));
  }
}

main();

module.exports = { assess, report };

