  const mean = calculateAverage(arr);
  /* Number.isNaN distinguishes the empty-array case from a real mean of 0. */
  const meanText = Number.isNaN(mean) ? 'n/a' : mean.toFixed(2);
  const trimmed = arr.length === 0 ? [] : withoutOutliers(arr);
  const trimmedMean = calculateAverage(trimmed);
  const trimmedText = Number.isNaN(trimmedMean) ? 'n/a' : trimmedMean.toFixed(2);
  return `${label}: n=${arr.length} mean=${meanText} sd=${standardDeviation(arr).toFixed(2)} trimmed=${trimmedText}`;
}

function main() {
  console.log(calculateAverage([10, 20, 30]));
  console.log(calculateAverage([5, 5, 5, 5]));

  const datasets = [
    ['temperatures', [18.5, 19.2, 20.1, 19.8, 34.0]],
    ['scores', [72, 88, 91, 64, 79, 85]],
    ['empty', []],
  ];

  for (const [label, values] of datasets) {
    console.log(formatReport(label, values));
  }

  try {
    calculateAverage([1, 2, 'three']);
  } catch (err) {
    /* Surfacing the guard keeps bad input visible instead of silently skewing results. */
    console.log(`rejected: ${err.message}`);
  }
}

main();

module.exports = { calculateAverage, standardDeviation, withoutOutliers, formatReport };

