const getCurrentDateFormatted = () => {
  const today = new Date(); // Create a new Date object for the current date and time.

  const year = today.getFullYear(); // Get the full year (e.g., 2023).

  // Get the month (0-indexed) and add 1 to make it 1-indexed.
  const month = (today.getMonth() + 1).toString().padStart(2, '0');

  // Get the day of the month.
  const day = today.getDate().toString().padStart(2, '0'); // Pad with a leading zero if necessary.

  // Concatenate the year, month, and day with hyphens.
  return `${year}-${month}-${day}`; // Return the formatted date string.
