// Dice rolling utilities: a single-die roller plus a few helpers built on top of it.

// Validate the die description once, so rollDice itself stays a one-liner.
function assertValidSides(sides) {
  if (!Number.isInteger(sides)) {
    throw new TypeError(`sides must be an integer, got ${typeof sides}: ${sides}`);
  }
  // A die needs at least two distinct faces to be a die at all.
  if (sides < 2) {
    throw new RangeError(`sides must be at least 2, got ${sides}`);
  }
}

function rollDice(sides) {
  assertValidSides(sides);
  // Math.random() is in [0, 1), so flooring the scaled value gives 0..sides-1.
  return Math.floor(Math.random() * sides) + 1;
}

// Roll the same die repeatedly and collect every result.
function rollMany(sides, count) {
  if (!Number.isInteger(count) || count < 1) {
    throw new RangeError(`count must be a positive integer, got ${count}`);
  }
  const results = [];
  for (let i = 0; i < count; i += 1) {
    results.push(rollDice(sides));
  }
  return results;
}

// Parse notation like "3d6" into the number of dice and the die size.
function parseNotation(notation) {
  const match = /^(\d*)d(\d+)$/i.exec(String(notation).trim());
  if (!match) {
    throw new SyntaxError(`unrecognised dice notation: ${notation}`);
  }
  // An omitted leading number means a single die, as in "d20".
  const count = match[1] === '' ? 1 : Number(match[1]);
  return { count, sides: Number(match[2]) };
}

// Roll a notation string and report both the individual faces and their sum.
function rollNotation(notation) {
  const { count, sides } = parseNotation(notation);
  const rolls = rollMany(sides, count);
  const total = rolls.reduce((sum, face) => sum + face, 0);
  return { notation, rolls, total };
}

function tally(rolls) {
  const counts = new Map();
  for (const face of rolls) {
    // Missing keys start at zero rather than undefined.
    counts.set(face, (counts.get(face) || 0) + 1);
  }
  return counts;
}

// Render a tally as sorted "face: bar (n)" lines for quick visual inspection.
function formatTally(counts) {
  const faces = [...counts.keys()].sort((a, b) => a - b);
  return faces
    .map((face) => {
      const n = counts.get(face);
      // Pad the face number so the bars line up for two-digit dice.
      const label = String(face).padStart(2, ' ');
      return `${label}: ${'#'.repeat(n)} (${n})`;
    })
    .join('\n');
}

function main() {
  console.log(`rollDice(6)  -> ${rollDice(6)}`);
  console.log(`rollDice(20) -> ${rollDice(20)}`);

  const attack = rollNotation('3d6');
  console.log(`${attack.notation} = [${attack.rolls.join(', ')}] total ${attack.total}`);

  // A thousand rolls of a d6 should spread fairly evenly across the six faces.
  console.log(formatTally(tally(rollMany(6, 60))));
}

main();

module.exports = { rollDice, rollMany, parseNotation, rollNotation, tally, formatTally };

