const daysBetweenDates = (date1Str, date2Str) => {
  // Create Date objects from the input strings.
  const date1 = new Date(date1Str);
  const date2 = new Date(date2Str);

  // Calculate the difference in milliseconds between the two dates.
  const diffTime = Math.abs(date2.getTime() - date1.getTime());

  // Define the number of milliseconds in one day.
  const oneDay = 1000 * 60 * 60 * 24; // milliseconds * seconds * minutes * hours

  // Calculate the number of days by dividing the time difference by one day's milliseconds.
  const diffDays = Math.round(diffTime / oneDay); // Round to handle potential daylight saving issues.

  // Return the calculated difference in days.
  return diffDays;
};

// Example usage:
