const isObjectEmpty = (obj) => {
  // Check if the input is actually an object and not null
  if (typeof obj !== 'object' || obj === null) {
    // Non-object or null inputs are considered not empty in this context
    return false;
  }

  // Iterate over the object's own enumerable properties
  for (const key in obj) {
    // Ensure the property belongs to the object itself, not its prototype chain
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      // If any own enumerable property is found, the object is not empty
      return false;
    }
  }
  // If the loop completes, no own enumerable properties were found
