// Utilities for working with file names and their extensions.

// Strip any directory component so separators inside a path are never
// mistaken for part of the base name.
function getBaseName(filename) {
  const lastSlash = Math.max(filename.lastIndexOf('/'), filename.lastIndexOf('\\'));
  return lastSlash === -1 ? filename : filename.slice(lastSlash + 1);
}

function getFileExtension(filename) {
  if (typeof filename !== 'string') {
    throw new TypeError('getFileExtension expects a string');
  }
  const base = getBaseName(filename);
  const dot = base.lastIndexOf('.');
  // No dot at all, or a leading dot (dotfiles such as ".bashrc" have no
  // extension), or a trailing dot with nothing after it.
  if (dot <= 0 || dot === base.length - 1) {
    return '';
  }
  return base.slice(dot + 1);
}

// "archive.tar.gz" -> "archive"; the stem is what remains once the single
// trailing extension is removed.
function getStem(filename) {
  const base = getBaseName(filename);
  const ext = getFileExtension(filename);
  return ext === '' ? base : base.slice(0, base.length - ext.length - 1);
}

function replaceExtension(filename, newExtension) {
  const clean = newExtension.replace(/^\.+/, '');
  const base = getBaseName(filename);
  const prefix = filename.slice(0, filename.length - base.length);
  const stem = getStem(filename);
  // Replacing with an empty extension simply drops the old one.
  if (clean === '') {
    return prefix + stem;
  }
  return prefix + stem + '.' + clean;
}

// Count how many files share each extension; files without one are collected
// under the key "(none)" so they still show up in the report.
function groupByExtension(filenames) {
  const groups = new Map();
  for (const name of filenames) {
    const ext = getFileExtension(name).toLowerCase();
    const key = ext === '' ? '(none)' : ext;
    if (!groups.has(key)) {
      groups.set(key, []);
    }
    groups.get(key).push(getBaseName(name));
  }
  return groups;
}

function formatReport(filenames) {
  const groups = groupByExtension(filenames);
  // Sort by descending count, then alphabetically to keep output stable.
  const entries = [...groups.entries()].sort((a, b) =>
    b[1].length - a[1].length || a[0].localeCompare(b[0]));
  return entries
    .map(([ext, names]) => `${ext.padEnd(8)} ${names.length}  ${names.join(', ')}`)
    .join('\n');
}

const samples = [
  'document.pdf',
  'archive.tar.gz',
  'nofileextension',
  '.bashrc',
  '/var/log/system.log',
  'C:\\Users\\ada\\notes.TXT',
  'report.final.',
  'photos/holiday.jpeg',
];

for (const name of samples) {
  // Quote the result so the empty-extension cases are visible.
  console.log(`${name} -> '${getFileExtension(name)}'`);
}
console.log(formatReport(samples));
console.log(replaceExtension('/var/log/system.log', '.txt'));

