const romanToInt = (roman) => {
  // Define a map for Roman numeral values
  const romanMap = {
    'I': 1,
    'V': 5,
    'X': 10,
    'L': 50,
    'C': 100,
    'D': 500,
    'M': 1000
  };

  let total = 0; // Initialize the total integer value
  let i = 0; // Initialize loop counter

  while (i < roman.length) { // Loop through the Roman numeral string
    const currentChar = roman[i]; // Get the current character
    const nextChar = roman[i + 1]; // Get the next character, if it exists

    const currentValue = romanMap[currentChar]; // Get the integer value of the current character

    // Check for subtractive cases (e.g., IV, IX)
    if (nextChar && romanMap[nextChar] > currentValue) {
      total += romanMap[nextChar] - currentValue; // Add the difference
      i += 2; // Skip both characters
    } else {
      total += currentValue; // Add the current character's value
      i += 1; // Move to the next character
    }
  }
  return total; // Return the final integer total
};

