const findMissingNumber = (nums) => {
  // Get the length of the input array.
  const n = nums.length; 
  // Calculate the expected sum of numbers from 0 to n.
  // The formula for the sum of an arithmetic series is n * (n + 1) / 2.
  const expectedSum = n * (n + 1) / 2; 

  let actualSum = 0; // Initialize a variable to store the actual sum of elements in the array.

  // Iterate through each number in the input array.
  for (let i = 0; i < n; i++) { 
    actualSum += nums[i]; // Add the current number to the actual sum.
  }

  // The difference between the expected sum and the actual sum
  // will be the missing number.
  return expectedSum - actualSum; 
};

