function calculateSimpleInterest(principal, rate, time) {
  // Ensure all inputs are numbers
  if (typeof principal !== 'number' || typeof rate !== 'number' || typeof time !== 'number') {
    // Throw an error if any input is not a number
    throw new Error('All inputs must be numbers.');
  }

  // Ensure principal and time are non-negative
  if (principal < 0 || time < 0) {
    // Interest cannot be calculated for negative principal or time
    throw new Error('Principal and time cannot be negative.');
  }

  // The formula for simple interest is P * R * T
  const interest = principal * rate * time;

  // Return the calculated simple interest
  return interest;
}

