function removeTask(tasks, taskToRemove) {
  const newTaskList = []; // Initialize an empty array to store the filtered tasks.

  for (let i = 0; i < tasks.length; i++) { // Loop through each task in the original list.
    const currentTask = tasks[i]; // Get the current task being processed.

    if (currentTask !== taskToRemove) { // Check if the current task is NOT the one to remove.
      newTaskList.push(currentTask); // If it's not the task to remove, add it to the new list.
    }
  } // The loop finishes here.

  return newTaskList; // Return the array containing tasks that were not removed.
}

