const calculateMode = (numbers) => {
  if (numbers.length === 0) { // Handle empty input array
    return [];
  }

  const frequencyMap = {}; // Object to store frequency of each number
  let maxFrequency = 0;    // Variable to track the highest frequency found

  for (const num of numbers) { // Iterate through each number in the input array
    frequencyMap[num] = (frequencyMap[num] || 0) + 1; // Increment frequency, initialize if not present
    if (frequencyMap[num] > maxFrequency) { // Check if current number's frequency is new max
      maxFrequency = frequencyMap[num];      // Update maximum frequency
    }
  }

  const modes = []; // Array to store the modes
  for (const num in frequencyMap) { // Iterate through the keys (numbers) in the frequency map
    if (frequencyMap[num] === maxFrequency) { // If a number's frequency matches the max
      modes.push(parseInt(num)); // Add the number (parsed to integer) to the modes array
    }
  }
  return modes; // Return the array of modes
};

