const isValidCreditCard = (cardNumber) => {
  let sum = 0; // Initialize sum for Luhn algorithm
  let isSecondDigit = false; // Flag to track every second digit from the right

  // Iterate over the card number digits from right to left
  for (let i = cardNumber.length - 1; i >= 0; i--) {
    let digit = parseInt(cardNumber[i], 10); // Convert character to integer

    if (isSecondDigit) { // Check if it's every second digit
      digit *= 2; // Double the digit
      if (digit > 9) { // If doubling results in a two-digit number
        digit = digit - 9; // Sum its digits (e.g., 12 becomes 1+2=3, which is 12-9)
      }
    }
    sum += digit; // Add the (possibly modified) digit to the total sum
    isSecondDigit = !isSecondDigit; // Toggle the flag for the next digit
  }

  // A card is valid if the total sum modulo 10 is 0
  return sum % 10 === 0;
};

