const isPowerOfTwo = (n) => {
  // Powers of two are always positive.
  if (n <= 0) {
    return false; // Zero and negative numbers are not powers of two.
  }

  // A number is a power of two if and only if it has exactly one bit set in its binary representation.
  // The bitwise AND operation (n & (n - 1)) clears the least significant set bit.
  // If n is a power of two, its binary representation is like 1000...0.
  // Then n - 1 would be 0111...1.
  // Performing n & (n - 1) on a power of two will result in 0.

  // Example: n = 8 (binary 1000)
  // n - 1 = 7 (binary 0111)
  // 8 & 7 = 0

  // Example: n = 6 (binary 0110)
  // n - 1 = 5 (binary 0101)
  // 6 & 5 = 4 (binary 0100), which is not 0.

  // This is an efficient bit manipulation trick.
  return (n & (n - 1)) === 0; // Check if the result of the bitwise operation is zero.
};
// Test cases below
