const findFirstDuplicate = (nums) => {
  const seenNumbers = new Set(); // Initialize a Set to store numbers encountered so far.

  for (let i = 0; i < nums.length; i++) { // Loop through each number in the input array.
    const currentNum = nums[i]; // Get the current number from the array.

    if (seenNumbers.has(currentNum)) { // Check if this number has been seen before.
      return currentNum; // If it has, this is our first duplicate, so return it.
    }
    seenNumbers.add(currentNum); // If not, add the current number to our set of seen numbers.
