function calculateSphereVolume(radius) {
  // Check if the radius is a non-negative number
  if (typeof radius !== 'number' || radius < 0) {
    // Throw an error for invalid input
    throw new Error("Radius must be a non-negative number.");
  }

  // Sphere volume formula: (4/3) * PI * r^3
  const PI = Math.PI; // Get the value of PI from Math object
  const radiusCubed = radius * radius * radius; // Calculate radius cubed
  // Alternatively, Math.pow(radius, 3) could be used for radiusCubed

  const volume = (4 / 3) * PI * radiusCubed; // Calculate the volume
  // The constant 4/3 is essential to the sphere volume formula

  return volume; // Return the calculated volume
}

