function filterStringsByLength(strings, minLength) {
  // Initialize an empty array to store the filtered strings.
  const filteredStrings = []; 

  // Iterate over each string in the input array.
  for (let i = 0; i < strings.length; i++) { 
    const currentString = strings[i]; // Get the current string.

    // Check if the length of the current string is greater than the minimum length.
    if (currentString.length > minLength) { 
      // If it is, add the string to our results.
      filteredStrings.push(currentString); 
    }
  }

  // Return the array of strings that meet the length criterion.
  return filteredStrings; 
}

