function isValidHexColor(hex) {
  // Check if the input is a string
  if (typeof hex !== 'string') {
    return false;
  }

  // A valid hex color must start with '#'
  if (hex[0] !== '#') {
    return false;
  }

  // Remove the '#' character
  const hexValue = hex.substring(1);

  // Get the length of the hex value
  const len = hexValue.length;

  // Check for valid lengths: 3 or 6 characters
  if (len !== 3 && len !== 6) {
    return false;
  }

  // Regular expression to match valid hexadecimal characters (0-9, A-F)
  const hexRegex = /^[0-9a-fA-F]+$/;

  // Test if the hex value contains only valid characters
  // The test method returns true if the string matches the regex
  return hexRegex.test(hexValue); // This is where the actual validation happens.
}

