// Rectangle utilities: build, validate and render ASCII art rectangles.

// Both dimensions must be positive integers; anything else is a caller error.
function validateDimensions(width, height) {
  const dims = { width: width, height: height };
  for (const name of Object.keys(dims)) {
    const value = dims[name];
    // One test rejects non-numbers, NaN, Infinity and fractional sizes.
    if (!Number.isInteger(value)) {
      throw new TypeError(name + ' must be an integer, got ' + String(value));
    }
    // A rectangle needs at least one column and one row of ink.
    if (value < 1) {
      throw new RangeError(name + ' must be at least 1, got ' + value);
    }
  }
}

function generateRectangle(width, height) {
  validateDimensions(width, height);
  // Every row of a solid rectangle is identical, so build the string once.
  const row = '*'.repeat(width);
  const rows = new Array(height);
  for (let i = 0; i < height; i += 1) {
    rows[i] = row;
  }
  return rows;
}

// A hollow variant: only the border cells carry ink.
function generateHollowRectangle(width, height) {
  validateDimensions(width, height);
  const solid = '*'.repeat(width);
  const rows = [];
  for (let y = 0; y < height; y += 1) {
    // Top and bottom edges stay solid, as does any rectangle thinner than 3.
    if (y === 0 || y === height - 1 || width < 3) {
      rows.push(solid);
    } else {
      rows.push('*' + ' '.repeat(width - 2) + '*');
    }
  }
  return rows;
}

// Join rows for terminal output; callers needing the array use it directly.
function renderRectangle(rows) {
  return rows.join('\n');
}

function describeRectangle(rows) {
  const height = rows.length;
  const width = rows[0].length;
  let filled = 0;
  for (const line of rows) {
    for (const ch of line) {
      // Count ink only, skipping the interior spaces of hollow rectangles.
      if (ch === '*') {
        filled += 1;
      }
    }
  }
  return width + 'x' + height + ', ' + filled + ' of ' + width * height + ' cells filled';
}

function main(argv) {
  const width = argv.length > 0 ? Number(argv[0]) : 3;
  const height = argv.length > 1 ? Number(argv[1]) : 2;
  const solid = generateRectangle(width, height);
  console.log(renderRectangle(solid));
  console.log(describeRectangle(solid));
  // Hollow output only differs once there is an interior to hollow out.
  if (width >= 3 && height >= 3) {
    const hollow = generateHollowRectangle(width, height);
    console.log(renderRectangle(hollow));
    console.log(describeRectangle(hollow));
  }
}

if (require.main === module) {
  main(process.argv.slice(2));
}

module.exports = {
  generateRectangle,
  generateHollowRectangle,
  renderRectangle,
  describeRectangle,
};

