// Utilities for locating the largest numeric value in a collection.

// Accepts only finite numbers; NaN and Infinity are rejected so that
// comparisons stay meaningful.
function isValidNumber(value) {
  return typeof value === 'number' && Number.isFinite(value);
}

// Returns the maximum value of the array, or throws when the input is unusable.
function findMax(numbers) {
  if (!Array.isArray(numbers)) {
    throw new TypeError('findMax expects an array of numbers');
  }
  if (numbers.length === 0) {
    throw new RangeError('findMax requires at least one element');
  }

  // Seed with the first element rather than -Infinity, so the result is
  // always an actual member of the array.
  let max = numbers[0];
  for (let i = 0; i < numbers.length; i += 1) {
    const current = numbers[i];
    if (!isValidNumber(current)) {
      throw new TypeError(`element at index ${i} is not a finite number: ${current}`);
    }
    if (current > max) {
      max = current;
    }
  }
  return max;
}

// Parses a whitespace- or comma-separated list of numbers from text input.
function parseNumberList(text) {
  return text
    .split(/[\s,]+/)
    .filter((token) => token.length > 0)
    .map((token) => {
      const value = Number(token);
      // Number('abc') yields NaN, which findMax would reject later; report
      // the offending token now while we still know its original text.
      if (Number.isNaN(value)) {
        throw new SyntaxError(`cannot parse "${token}" as a number`);
      }
      return value;
    });
}

// Formats a one-line report describing where the maximum was found.
function describeMax(numbers) {
  const max = findMax(numbers);
  const position = numbers.indexOf(max);
  return `max=${max} at index ${position} of ${numbers.length} values`;
}

function main(args) {
  const inputs = args.length > 0 ? [args.join(' ')] : ['1 5 2 8 3', '-10 -2 -5'];
  for (const line of inputs) {
    try {
      console.log(describeMax(parseNumberList(line)));
    } catch (err) {
      // Bad user input should not crash the driver; report and continue.
      console.error(`${line}: ${err.message}`);
    }
  }
}

// Only run the driver when executed directly, not when required as a module.
if (typeof require !== 'undefined' && typeof module !== 'undefined' && require.main === module) {
  main(process.argv.slice(2));
}

if (typeof module !== 'undefined') {
  module.exports = { findMax, isValidNumber, parseNumberList, describeMax };
}

