// Module for extracting even numbers from numeric input and reporting on them.

// Values arriving from text input (CLI args, files) need coercion before any parity test.
function parseNumber(token) {
  const trimmed = String(token).trim();
  // An empty token would coerce to 0, which is a silent data error, so reject it.
  if (trimmed === '') {
    throw new Error('empty token is not a number');
  }
  const value = Number(trimmed);
  if (!Number.isFinite(value)) {
    throw new Error('cannot parse ' + trimmed + ' as a finite number');
  }
  return value;
}

// Parity is only meaningful for integers, so fractions are never considered even.
function isEven(value) {
  return Number.isInteger(value) && value % 2 === 0;
}

function filterEvenNumbers(numbers) {
  if (!Array.isArray(numbers)) {
    throw new TypeError('filterEvenNumbers expects an array');
  }
  const evens = [];
  for (const entry of numbers) {
    // Strings and other non-numbers are normalised first, keeping the filter total.
    const value = typeof entry === 'number' ? entry : parseNumber(entry);
    if (isEven(value)) {
      evens.push(value);
    }
  }
  // A fresh array is returned, so the caller's input is never mutated.
  return evens;
}

function summarise(original, evens) {
  const sum = evens.reduce((acc, n) => acc + n, 0);
  return {
    total: original.length,
    kept: evens.length,
    dropped: original.length - evens.length,
    sum: sum,
    // Guard against division by zero for an empty result set.
    mean: evens.length === 0 ? null : sum / evens.length
  };
}

function formatReport(original, evens) {
  const stats = summarise(original, evens);
  const lines = [
    'input:  [' + original.join(', ') + ']',
    'evens:  [' + evens.join(', ') + ']',
    'kept ' + stats.kept + ' of ' + stats.total + ', dropped ' + stats.dropped + ', sum ' + stats.sum
  ];
  // Only mention the mean when at least one even number survived the filter.
  if (stats.mean !== null) {
    lines.push('mean:   ' + stats.mean);
  }
  return lines.join('\n');
}

function main(argv) {
  // With no arguments, fall back to the two documented sample inputs.
  const samples = argv.length > 0
    ? [argv.map(parseNumber)]
    : [[1, 2, 3, 4, 5, 6], [7, 9, 11]];

  for (const sample of samples) {
    console.log(formatReport(sample, filterEvenNumbers(sample)));
    console.log('');
  }
}

main(process.argv.slice(2));

module.exports = { filterEvenNumbers, isEven, parseNumber, summarise, formatReport };

