// Compound interest utilities.
// A = P * (1 + r/n)^(n*t)

// Validates the four inputs and throws on anything that would poison the maths.
function validateInputs(principal, rate, n, years) {
  const labelled = { principal, rate, n, years };
  for (const [name, value] of Object.entries(labelled)) {
    // Number.isFinite rejects strings, NaN and the infinities in one go.
    if (!Number.isFinite(value)) {
      throw new TypeError(`${name} must be a finite number, got ${String(value)}`);
    }
  }
  if (principal < 0) {
    throw new RangeError('principal cannot be negative');
  }
  // A zero or fractional compounding frequency has no financial meaning.
  if (!Number.isInteger(n) || n < 1) {
    throw new RangeError('n must be a positive integer number of periods per year');
  }
  if (years < 0) {
    throw new RangeError('years cannot be negative');
  }
}

function calculateCompoundInterest(principal, rate, n, years) {
  validateInputs(principal, rate, n, years);
  const periodRate = rate / n;
  const periods = n * years;
  return principal * Math.pow(1 + periodRate, periods);
}

// Interest earned only, i.e. the growth on top of the original deposit.
function interestEarned(principal, rate, n, years) {
  return calculateCompoundInterest(principal, rate, n, years) - principal;
}

// Builds a year-by-year balance table, useful for showing growth over time.
function schedule(principal, rate, n, years) {
  validateInputs(principal, rate, n, years);
  const rows = [];
  // Whole years are tabulated; a trailing partial year gets its own final row.
  const wholeYears = Math.floor(years);
  for (let year = 1; year <= wholeYears; year += 1) {
    const balance = calculateCompoundInterest(principal, rate, n, year);
    rows.push({ year, balance });
  }
  if (years > wholeYears) {
    rows.push({ year: years, balance: calculateCompoundInterest(principal, rate, n, years) });
  }
  return rows;
}

function formatMoney(amount) {
  // toFixed rounds half-up on the decimal string, which is what statements show.
  return `$${amount.toFixed(2)}`;
}

function report(principal, rate, n, years) {
  const final = calculateCompoundInterest(principal, rate, n, years);
  const lines = [
    `${formatMoney(principal)} at ${(rate * 100).toFixed(2)}% compounded ${n}x/year for ${years} year(s)`,
    `  final:    ${formatMoney(final)} (exact ${final})`,
    `  interest: ${formatMoney(interestEarned(principal, rate, n, years))}`,
  ];
  for (const row of schedule(principal, rate, n, years)) {
    lines.push(`  year ${row.year}: ${formatMoney(row.balance)}`);
  }
  return lines.join('\n');
}

function main() {
  console.log(report(1000, 0.05, 12, 1));
  console.log(report(5000, 0.04, 4, 3));
  console.log(report(250, 0.072, 1, 2.5));
  try {
    calculateCompoundInterest(1000, 0.05, 0, 1);
  } catch (err) {
    // Surfacing the guard keeps a bad frequency from silently returning Infinity.
    console.log(`rejected: ${err.message}`);
  }
}

main();

