  if (duplicates.length > 0) {
    throw new Error(`duplicate values: ${duplicates.join(', ')}`);
  }
  return invertObject(obj);
}

/* Renders an object for logging, quoting strings so that {1: 'a'} stays */
/* distinguishable from {1: a}. */
function formatObject(obj) {
  const parts = Object.entries(obj).map(([key, value]) => {
    const shown = typeof value === 'string' ? `'${value}'` : String(value);
    return `${key}: ${shown}`;
  });
  return `{${parts.join(', ')}}`;
}

